const $=q=>document.querySelector(q),app=$('#app'),KEY='if-world-save-v1';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=moneyText;
const date=m=>m.replaceAll('-','.');let helpSection='play',helpReturn={landing:true,tab:'study'};let avatarMotion=true;let state=null,saved=null,tab='life',landing=true,filter='all',storageOK=true,menuOpen=false,storyMode=true,shopCategory='home',marketStock='chip',marketPeriod=36;let lotteryRecords=new Map(CATALOG.map(r=>[r.round,r]));
const START_CHOICES=[{id:'1',year:'2002',title:'첫 번째 로또',description:'실제 1등은 없었지만, 그날 당신이 당첨됐다면.',tag:'1회 · 가상 지급 규칙'},{id:'19',year:'2003',title:'역대 최고 1등 당첨금',description:'2003년 4월 12일. 세전 40,722,959,400원으로 다른 인생을 시작해요.',tag:'19회 · 1등 1게임'},{id:'custom',year:'IF',title:'내가 고른 그날',description:'원하는 회차를 고르고 자료를 입력하거나 불러오세요.',tag:'회차 직접 선택'}];
try{const records=JSON.parse(localStorage.getItem(KEY+'-lottery')||'[]');for(const record of records){const checked=validateRecord(record);lotteryRecords.set(checked.round,checked);}storyMode=localStorage.getItem(KEY+'-pace')!=='manual';const data=localStorage.getItem(KEY);if(data){const parsed=JSON.parse(data);if(validateSave(parsed))saved=parsed;else toast('저장된 기록을 읽을 수 없습니다. 새로 시작하거나 백업을 불러오세요.');}}catch{storageOK=false;}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500);}
function save(){saved=state;try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('자동 저장이 불가능합니다. 기록 파일을 내려받아 보관해 주세요.');}}
function header(){return `<header class="topbar ${landing?'on-dark':''}"><div class="nav-container"><button class="brand" data-ui="home" aria-label="IF 세계 시작 화면"><span class="brand-mark">IF<span class="brand-dot">.</span></span><span>세계</span></button><nav id="primary-nav" class="primary-nav ${menuOpen?'is-open':''}" aria-label="주요 메뉴"><button class="nav-link" ${landing?'data-scroll="eras"':state?'data-tab="study"':'data-ui="home"'}>${landing||!state?'시작점 고르기':'나의 삶'}</button><button class="nav-link" data-ui="guide">플레이 안내</button><button class="nav-link" data-ui="data">세계의 규칙</button><button class="nav-link" data-ui="${saved?'resume':'import'}">${saved?'나의 기록':'기록 불러오기'}</button></nav><div class="header-right"><button class="btn nav-cta small" data-ui="${saved?'resume':'new'}">${saved?'이어서 살기':'새로운 삶 시작'} <span>↗</span></button><button class="menu-toggle" data-ui="menu" aria-expanded="${menuOpen}" aria-controls="primary-nav" aria-label="${menuOpen?'메뉴 닫기':'메뉴 열기'}"><span></span><span></span></button></div></div></header>`;}
const footer=()=>`<footer class="footer"><div class="footer-main"><span class="footer-brand">IF<span>.</span> 세계</span><span>같은 역사.<br>다른 선택.</span><button class="text-button" data-ui="new">새로운 삶 시작하기 ↗</button></div><div class="footer-bottom"><span>IF WORLD / ECONOMIC HISTORY THROUGH A LIFE</span><button class="text-button" data-ui="guide">플레이 안내 · 패치노트 ↗</button><span>학습용 베타 · 금융 가격과 생활 비용은 모형 · 브라우저에 기록 저장</span></div></footer>`;

function render(){document.body.classList.toggle('motion-paused',!avatarMotion);document.body.classList.toggle('landing-mode',landing);document.body.classList.toggle('game-mode',!landing);app.innerHTML=header()+(landing?renderLanding():renderGame())+footer();applyReadability(app);}

function renderLanding(){return `<main id="main"><section class="landing-hero"><div class="hero-container"><div class="hero-topline"><span class="eyebrow">LEARN HISTORY. LIVE A DIFFERENT LIFE.</span><span class="pill"><span class="dot"></span> IF : 로또에 당첨됐다면</span></div><div class="hero-grid"><div class="hero-copy"><h1 class="opportunity-title" aria-label="그날, 나에게 기회가 왔다면?">그날,<br> 나에게 기회가<br> <span>왔다면?</span></h1><div class="hero-description"><span class="hero-line"></span><p>한 사람의 삶으로 경험하는 한국 경제사.<br>시대의 사건을 만나고, 선택하고, 이유를 이해해요.<br>나의 성장과 경제의 변화를 함께 기록합니다.</p></div><div class="hero-buttons"><button class="btn" data-ui="learn-new">출생부터 배우기 <span>↗</span></button><button class="btn ghost" data-ui="new">로또 당첨부터 시작 <span>↗</span></button></div>${saved?`<button class="resume" data-ui="resume"><span class="resume-indicator"></span><span><b>${escape(saved.name)}의 세계가 기다리고 있어요.</b><small>${date(saved.month)} · 순자산 ${won(worth(saved))}</small></span><span class="resume-arrow">↗</span></button>`:''}</div><div class="world-visual" aria-hidden="true"><div class="world-coordinate">IF / PARALLEL WORLD</div><div class="world-type">IF</div><svg class="world-orbit" viewBox="0 0 560 560"><ellipse cx="280" cy="280" rx="250" ry="120" transform="rotate(-35 280 280)"/><ellipse cx="280" cy="280" rx="250" ry="120" transform="rotate(35 280 280)"/><circle cx="280" cy="280" r="185" class="orbit-faint"/><path d="M40 440 C180 440 190 150 480 120" class="orbit-blue"/><circle cx="101" cy="280" r="8" class="orbit-point"/><circle cx="473" cy="179" r="7" class="orbit-point hollow"/><circle cx="420" cy="398" r="5" class="orbit-point white"/></svg><span class="world-label label-a">2002<br><small>하나의 시작</small></span><span class="world-label label-b">2026<br><small>다른 오늘</small></span><span class="world-foot">THE FUTURE IS YOUR CHOICE.</span></div></div><div class="hero-bottom"><span>HISTORY IS FIXED. YOUR LIFE IS NOT.</span><span>스크롤해서 다른 삶을 만나보세요 ↓</span></div></div></section><section id="eras" class="era-section section-container"><div class="section-title"><div><span class="eyebrow">01 / THE BEGINNING</span><h2>어느 시절의<br>당신으로 시작할까요?</h2></div><p>갖고 싶던 집과 차, 해보고 싶던 일들.<br>시작점은 정해도 이후의 선택은 당신에게 있어요.</p></div><div class="era-list">${START_CHOICES.map((sc,i)=>`<button class="era-row" data-scenario="${sc.id}"><span class="era-number">0${i+1}</span><span class="era-year">${sc.year}<span>↗</span></span><span class="era-copy"><b>${escape(sc.title)}</b><small>${escape(sc.description)}</small></span><span class="era-tag">${sc.tag}</span><span class="era-arrow">↗</span></button>`).join('')}</div><div class="era-note"><span class="dot"></span> 시작 월과 회차와 인물을 직접 고릅니다. 1~1,245회 전체 회차에서 시작할 수 있습니다.</div></section><section id="how" class="how-section"><div class="section-container"><div class="section-title"><div><span class="eyebrow">02 / YOUR LIFE, YOUR RULES</span><h2>돈을 얻는 순간보다,<br>그다음의 선택이 중요하니까.</h2></div></div><div class="how-grid"><article><span class="step-num">01</span><h3>그 시대의 상황을 살펴봐요.</h3><p>아직 결과를 모르는 상황에서 판단의 기준을 정해요.<br>어린 시절에는 가족 가계를, 성장하면 나의 생활과 자산을 살펴봅니다.</p><span class="how-detail">현금 / 예금 / 달러 / 금 / 테마 주식 / 나의 생활</span></article><article><span class="step-num">02</span><h3>선택과 역사 사이를 이해해요.</h3><p>사건 이후 실제 기록과 게임 결과를 확인해요.<br>경제 변화가 가계와 산업에 닿는 경로를 짧은 해설로 읽습니다.</p><span class="how-detail">경제 / 정치 / 사회 / 문화 / 나의 일상</span></article><article><span class="step-num">03</span><h3>다른 선택을 비교하고 기록해요.</h3><p>같은 돈을 현금·예금·달러·주식에 두었다면 어땠을까요?<br>개념 수첩과 경제사 타임라인에 나의 학습 발자국을 남깁니다.</p><span class="how-detail">시간 진행 / 선택 기록 / 결산</span></article></div></div></section><section class="faq-section section-container"><div><span class="eyebrow">03 / BEFORE YOU START</span><h2>이 세계에<br>들어오기 전에.</h2><button class="btn secondary" data-ui="data">자료와 가정 자세히 보기 ↗</button></div><div class="faq-list"><details><summary>실제 로또 당첨금과 물가를 사용하나요?<span>+</span></summary><p>1~1,245회 자료를 내장했습니다. 1~1,156회는 두 사본을 대조했고 최근 89회는 민간 API 자료입니다. 로또 수령액 기본은 70% 가정이며 실제 당시 당첨금 세금 정산은 미연결입니다. 물가·집값·은행 금리는 모형입니다. 예금 이자 공제 일부는 시기별 기본 세율을 참고합니다.</p></details><details><summary>역사 속 사건도 바꿀 수 있나요?<span>+</span></summary><p>역사적 사건의 발생은 그대로입니다. 그 안에서 나의 소비, 일, 자산과 생활을 바꾸는 게임이에요. 사건의 사실과 출처는 게임에서 가정한 선택 효과와 구분합니다.</p></details><details><summary>중간에 그만두면 기록은 어떻게 되나요?<span>+</span></summary><p>같은 브라우저에서 자동으로 저장됩니다. 기록 파일을 내려받으면 다른 환경에서도 불러올 수 있어요. 새 삶은 저장 슬롯을 덮어쓰므로 기존 기록을 먼저 보관해 주세요.</p></details></div></section><section class="closing-section"><div class="section-container"><span class="eyebrow">THERE IS NO SINGLE RIGHT LIFE.</span><h2>당신의 다른 세계는<br>어떤 모습일까요?</h2><button class="btn" data-ui="new">지금, 다른 삶 시작하기 ↗</button></div></section></main>`;}

function renderGame(){if(tab==='guide')return renderHelp(helpSection);if(tab==='data'&&!state)return `<main id="main" class="workspace">${docs()}<button class="btn spacer" data-ui="home">시작 화면으로</button></main>`;
 const s=state;return `<main id="main" class="workspace"><div class="page-head compact-page-head"><div><div class="eyebrow">IF 세계 · ${s.rules?.difficulty==='hard'?'어려움':'보통'}</div><h1>${escape(s.name)}의 또 다른 삶</h1><p>${REGIONS[s.region].name} · ${age(s)}세 · ${{male:'남성',female:'여성',unspecified:'성별 미설정'}[s.gender||'unspecified']} · ${s.startMode==='birth'&&age(s)<19?'가족 가계 관찰':s.job?'직장 생활':'자유로운 생활'}${s.business?' · 가게 운영':''}</p></div><div class="date-box"><div class="eyebrow">${s.ended?'이 삶의 도착점':'지금, 당신의 시간'}</div><div class="date full-date">${date(s.month===s.start?(s.startDate||s.month):s.month)}</div></div></div><nav class="tabs compact-nav" aria-label="게임 화면">${[['study','진행'],['finance','자산'],['living','생활'],['records','기록']].map(([id,title])=>`<button class="tab ${(tab===id||id==='finance'&&['market','economy'].includes(tab)||id==='living'&&['assets','shop','world','life'].includes(tab)||id==='records'&&['journal','notebook','data'].includes(tab))?'active':''}" data-tab="${id}" aria-current="${tab===id?'page':'false'}">${title}</button>`).join('')}</nav>${s.month>END?'<div class="notice future-notice">가상 미래에 들어왔습니다. 이후 경제와 개인 사건은 게임 가정이며, 실제로 일어난 역사로 표시하지 않습니다.</div>':''}${!storageOK?'<div class="notice">자동 저장이 불가능한 환경입니다. ‘선택의 기록’에서 기록 파일을 내려받아 주세요.</div>':''}${tab==='living'?renderLiving(s,{escape,won,date}):tab==='finance'?renderFinance(s,{escape,won,date}):tab==='records'?renderRecords(s,{escape,won,date}):tab==='study'?renderLearning(s,{escape,won,date}):tab==='notebook'?renderNotebook(s,{escape,won,date}):tab==='economy'?renderKorea(s,{escape,won,date}):tab==='market'?renderMarket(s,{escape,won,date,selected:marketStock,period:marketPeriod}):tab==='life'?(s.startMode==='birth'&&age(s)<19?renderLearning(s,{escape,won,date}):life()):tab==='world'?renderWorld(s,{escape,won,date}):tab==='shop'?shop():tab==='assets'?assets():tab==='journal'?journal():docs()}</main>`;}
function health(){const s=state;return `<div class="card status-card"><h3>돈 말고, 나의 상태</h3><div class="stat-row"><span>생활 만족</span><b>${s.happy} / 100</b></div><div class="bar" role="meter" aria-label="생활 만족" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.happy}"><span style="width:${s.happy}%"></span></div><div class="stat-row"><span>건강</span><b>${s.health} / 100</b></div><div class="bar" role="meter" aria-label="건강" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.health}"><span style="width:${s.health}%"></span></div><div class="note spacer">선택에 따른 게임 지표입니다.<br>의학적·심리적 예측이 아니에요.</div></div>`;}
function balance(){const s=state;return `<section class="metric-strip" aria-label="자산 요약"><div class="metric primary-metric"><span class="eyebrow">현재 순자산</span><strong>${won(worth(s))}</strong><small>시작보다 ${won(worth(s)-s.initial)}</small></div><div class="metric"><span class="eyebrow">사용 가능한 현금</span><strong>${won(s.cash)}</strong><small>바로 선택에 사용할 수 있는 돈</small></div><div class="metric"><span class="eyebrow">물가 반영 구매력</span><strong>${won(worth(s)/s.cpi)}</strong><small>시작 당시의 물가 기준 · 게임 가정</small></div></section>`;}

function progress(){const s=state;if(s.lifetime){const progress=Math.min(100,age(s));return `<div class="progress-label"><span>${age(s)}세 · ${simulationPhase(s)}</span><span>75~100세 사이 종료</span></div><div class="progress-bar"><span style="width:${progress}%"></span></div>`;}const total=monthIndex(END)-monthIndex(s.start),done=monthIndex(s.month)-monthIndex(s.start);return `<div class="progress-label"><span>당첨 후 ${Math.floor(done/12)}년 ${done%12}개월</span><span>2026.10까지</span></div><div class="progress-bar"><span style="width:${total?Math.min(100,done/total*100):100}%"></span></div>`;}
function life(){const s=state;return `${paceControl()}${worldPreview()}${balance()}<div class="game-grid"><section class="life-main">${s.ended?summary():eventCard()}<div class="life-bottom"><div class="card profile"><span class="eyebrow">MY EVERYDAY</span><h3>지금의 생활</h3><div class="profile-row"><span>주거</span><b>${s.home?'자가':'월세'}</b></div><div class="profile-row"><span>차량</span><b>${escape(s.vehicle?.name||(s.car?'보유':'없음'))}</b></div><div class="profile-row"><span>기본 생활비</span><b>${won(s.living*s.cpi)}</b></div><button class="text-button" data-tab="assets">생활 바꾸기 ↗</button></div>${health()}</div><div class="journal-mini"><div class="section-heading"><div><span class="eyebrow">RECENT CHOICES</span><h3>내가 지나온 선택</h3></div><button class="text-button" data-tab="journal">전체 기록 ↗</button></div>${s.log.filter(l=>l.type!=='month').slice(-3).reverse().map(l=>`<div class="journal-item"><time>${date(l.month)}</time><div><h4>${escape(l.title)}</h4><p>${escape(l.text)}</p></div></div>`).join('')}</div></section><aside class="stack right-rail"><div class="card next-panel"><span class="eyebrow">THE NEXT CHAPTER</span><h3>다음 이야기로</h3>${progress()}<p>${s.pending?'사건을 선택하면 다음 달로 넘어갈 수 있어요.':'다음 달의 생활과 사건을 만나보세요.'}</p><div class="time-controls"><button class="btn" data-advance="12" ${s.pending||s.ended?'disabled':''}>다음 사건까지 <span>→</span></button><button class="btn secondary small" data-advance="1" ${s.pending||s.ended?'disabled':''}>한 달만 진행</button></div><p class="note">최대 12개월 계산 · 사건이 나오면 멈춰요.</p></div>${plans()}<div class="card flow-panel"><span class="eyebrow">MONTHLY CASH FLOW</span><h3>매달의 돈 흐름</h3>${flows()}<p class="note spacer">현재 조건의 예상값 · 게임 가정</p></div><div class="card chart-panel"><span class="eyebrow">THE PATH YOU TOOK</span><h3>자산이 지나온 길</h3>${chart()}<div class="chart-caption"><span>${date(s.start)}</span><span>${date(s.month)}</span></div></div></aside></div>`;}

function paceControl(){return `<div class="pace-control"><div><span class="mini-label">STORY PACE</span><span class="pace-description">${storyMode?'선택하면 다음 사건으로 바로 이어져요.':'생활을 조정하고 직접 시간을 보내세요.'}</span></div><div class="pace-buttons" role="group" aria-label="진행 방식"><button data-pace="story" aria-pressed="${storyMode}" class="${storyMode?'active':''}">이야기 중심</button><button data-pace="manual" aria-pressed="${!storyMode}" class="${!storyMode?'active':''}">직접 진행</button></div></div>`;}
function choiceFeedback(){const choice=state.log.findLast(l=>l.type==='choice');if(!choice)return '';const result=state.log.findLast(l=>l.type==='result'&&l.id>choice.id);return `<div class="choice-feedback"><span class="feedback-check">✓</span><div><span class="eyebrow">${result?'돌아온 결과':'지난 선택'} · ${date((result||choice).month)}</span><b>${escape((result||choice).title)}</b><small>${escape((result||choice).text)}</small></div></div>`;}
function plans(){const s=state,decisions=s.log.filter(l=>l.type==='choice').length,buffer=s.cash+s.deposit>=expenses(s)*6;const goals=[{title:'내가 고른 집에서 살기',detail:s.homeDetails?.name||'위시리스트에서 집을 골라요',done:s.home>0},{title:'내 드림카 타기',detail:s.vehicle?.name||'원했던 차를 직접 골라요',done:Boolean(s.car)},{title:'나만의 취향 채우기',detail:`소장품 ${(s.collection||[]).length}개 · 여행 ${(s.memories||[]).length}번`,done:Boolean((s.collection||[]).length||(s.memories||[]).length)}];return `<div class="card plans-panel"><span class="eyebrow">SMALL STEPS, YOUR LIFE</span><h3>말로만 하던 나의 꿈</h3>${goals.map(g=>`<div class="goal-row ${g.done?'achieved':''}"><span class="goal-dot">${g.done?'✓':'○'}</span><div><b>${g.title}</b><small>${escape(g.detail)}</small></div></div>`).join('')}<p class="note">비싼 것보다 내가 원했던 생활을 골라보세요.</p>${s.deferred.length?`<div class="pending-plans"><span class="eyebrow">진행 중인 계획</span>${s.deferred.map(d=>`<div><b>${date(d.month)}</b><small>${escape(d.title)}</small></div>`).join('')}</div>`:''}</div>`;}
function eventCard(){if(['history-study','growth'].includes(state.pending?.kind))return renderStudyEvent(state,{escape,won,date});const s=state,e=s.pending;const feedback=choiceFeedback();if(!e)return `<article class="card event">${feedback}<div class="event-top"><span class="mini-label">내 삶 · 잠시 고르는 시간</span><span class="eyebrow">${date(s.month)}</span></div><h2>큰 사건이 없는 날에도,<br>삶은 계속된다.</h2><p>내 집, 드림카, 갖고 싶던 물건을 고르거나.<br>다음 달로 넘어가기 전에 지금의 생활을 살펴보세요.</p><div class="legend"><span>${s.job?'일을 계속하는 중':'근로소득 없음'}</span><span>${s.home?'내 집에서 생활':'월세로 생활'}</span><span>예상 월 지출 ${won(expenses(s))}</span></div>${shoppingShortcuts()}<button class="btn secondary spacer" data-tab="assets">자산과 생활 살펴보기 →</button><div class="intro-rule">역사 사건은 발생한 달에 표시됩니다. 그 사이에는 3개월마다 개인 사건을 만나요. 다음 사건까지 한 번에 이동할 수 있어요.</div></article>`;
 return `<article class="card event">${feedback}<div class="event-top"><span class="mini-label">${e.future?'가상 시장 사건':e.url?'역사적 사실':'가상 개인 사건'} · ${escape(e.category||'내 삶')}</span><span class="eyebrow">${escape(e.date||date(s.month))}</span></div><h2>${escape(e.title)}</h2>${e.origin?`<div class="story-origin">이 이야기가 열린 이유 · ${escape(e.origin)}</div>`:''}<p>${escape(e.text)}</p>${e.economicId?renderImpact(s,{escape,won,date}):''}${e.url?`<a class="source" href="${escape(e.url)}" target="_blank" rel="noopener noreferrer">${escape(e.source)} · 사건 출처 ↗</a>`:''}<div class="game-assumption">${e.kind==='civic'?'정치적 입장에 따른 보상·벌점은 없습니다.':'아래 비용·수익·생활 효과는 역사적 사실이 아닌 게임 가정입니다.'}</div><div class="options">${choices(s).map((c,i)=>`<button class="choice" data-choice="${c.id}" ${choiceCost(s,c.id)>s.cash?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span><strong>${escape(c.title)}</strong><small>${escape(c.detail)}${choiceCost(s,c.id)>s.cash?' · 현금 부족':''}</small></span><span class="arrow">↗</span></button>`).join('')}</div>${shoppingShortcuts()}<div class="intro-rule">선택 전에 ‘자산과 생활’에서 예금을 인출하거나 보유 주식을 매도할 수 있어요.</div></article>`;}
function flows(){const s=state,eco=gameEconomy(s),salary=salaryIncome(s),biz=businessValue(s),interest=s.deposit*eco.deposit/12,spend=expenses(s);return [['급여',salary],['사업손익',biz],['예금 이자',interest],['생활·주거비',-spend],['대출 예정 원리금',-loanDue(s)],['예상 월 잔액',salary+biz+interest-spend-loanDue(s)]].map(([label,value])=>`<div class="flow-row"><span>${label}</span><b class="${value<0?'negative':'positive'}">${won(value)}</b></div>`).join('');}
function chart(){const points=state.timeline.slice(),latest={month:state.month,worth:worth(state)};if(points.length)points[points.length-1]=latest;else points.push(latest);const vals=points.map(x=>x.worth),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const coords=points.map((p,i)=>`${16+(points.length===1?0:i/(points.length-1)*228)},${126-(p.worth-min)/range*95}`).join(' ');return `<svg class="chart" viewBox="0 0 260 155" role="img" aria-label="순자산 추이. 시작 ${won(state.initial)}, 현재 ${won(worth(state))}"><path d="M16 32H244 M16 79H244 M16 126H244" fill="none" stroke="#e3e3e3" stroke-dasharray="3 4"/><polyline points="${coords}" fill="none" stroke="#218aff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${16+(points.length===1?0:228)}" cy="${126-(latest.worth-min)/range*95}" r="4" fill="#218aff"/></svg><p class="chart-range">범위 ${won(min)} ~ ${won(max)}</p>`;}
function shoppingShortcuts(){return `${state?.market?'<div class="shopping-shortcuts market-shortcut"><span>사건을 읽고 자금을 바꿔보세요.</span><button class="btn secondary small" data-tab="market">달러·금·테마 주식 매매 →</button></div>':''}<div class="shopping-shortcuts"><span>당첨되면 하고 싶었던 일</span><div><button data-shop="home">내 집 고르기 ↗</button><button data-shop="car">드림카 고르기 ↗</button><button data-shop="luxury">명품 쇼핑 ↗</button></div></div>`;}
function productArt(item){const common='fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';let art='';
 if(item.type==='home'){art=item.icon==='garden'?'<path d="M35 89V53L76 25l41 28v36z M23 54l53-37 53 37 M64 89V62h23v27 M46 55h12v13H46z M96 55h12v13H96z M127 89V64 M118 63c-12-18 14-25 16-10 10-2 12 11 0 12 M20 91h123"/>':item.icon==='tower'?'<path d="M43 92V22h59v70 M32 92h84 M55 34h8 M80 34h8 M55 49h8 M80 49h8 M55 65h8 M80 65h8 M66 92V79h15v13 M49 22V13h47v9"/>':'<path d="M35 92V35h84v57 M25 92h104 M46 35V20h60v15 M48 49h12v12H48z M88 49h12v12H88z M48 73h12v12H48z M88 73h12v12H88z M68 92V71h11v21"/>';
 }else if(item.type==='car'){art=item.icon==='suv'?'<path d="M20 80V59l19-8 13-22h54l24 29 13 5v17H20 M44 50h61l-10-16H56z M15 80h134 M24 66h13 M125 66h14"/><circle cx="43" cy="81" r="11"/><circle cx="119" cy="81" r="11"/>':item.icon==='sport'?'<path d="M15 77V64l38-12 25-19h29l21 24 21 8v12H15 M53 51h72 M75 38l-13 13 M95 35v17 M19 68h17 M130 67h14"/><circle cx="42" cy="79" r="11"/><circle cx="121" cy="79" r="11"/>':'<path d="M17 78V60l22-6 22-23h48l21 25 16 6v16H17 M42 53h82 M66 37l-15 16 M89 35v18 M24 66h14 M128 66h11"/><circle cx="43" cy="79" r="11"/><circle cx="119" cy="79" r="11"/>';
 }else if(item.icon==='watch'){art='<path d="M65 27l4-15h26l4 15 M65 85l4 16h26l4-16"/><circle cx="82" cy="56" r="31"/><circle cx="82" cy="56" r="25"/><path d="M82 39v18l11 7 M113 51h7v10h-7 M82 28v4 M82 80v4 M54 56h4 M107 56h4"/>';
 }else if(item.icon==='bag'){art='<path d="M39 41h86l6 51H33z M60 42V30a22 22 0 0144 0v12 M44 42v44h76V42 M76 63h12v8H76z"/>';
 }else if(item.icon==='jewelry'){art='<path d="M39 26c0 61 85 61 85 0 M58 39c5 23 44 23 49 0 M71 74l11-9 11 9-11 16z M75 91h14"/><circle cx="47" cy="32" r="3"/><circle cx="116" cy="32" r="3"/>';
 }else if(item.icon==='wardrobe'){art='<path d="M58 22l24 11 24-11 25 18-12 23-15-9v39H59V54l-15 9-13-23z M69 26l13 29 13-29 M82 55v38 M68 75h4 M93 75h4"/>';
 }else if(item.icon==='audio'){art='<rect x="31" y="20" width="40" height="76" rx="4"/><rect x="94" y="20" width="40" height="76" rx="4"/><circle cx="51" cy="69" r="13"/><circle cx="114" cy="69" r="13"/><circle cx="51" cy="35" r="6"/><circle cx="114" cy="35" r="6"/>';
 }else{art='<path d="M42 95V28h79v67 M63 28v-9h37v9 M42 42h79 M54 37v48 M110 37v48 M42 86h79 M52 95v6 M111 95v6 M64 48h34v25H64z M73 61h16 M84 49v24"/>';}return `<svg viewBox="0 0 164 112" aria-hidden="true"><g ${common}>${art}</g></svg>`;}
function shop(){const s=state,era=eraWishlist(s),category=SHOP_CATEGORIES.find(c=>c.id===shopCategory)||SHOP_CATEGORIES[0];const items=SHOP_ITEMS.filter(item=>item.type===category.id);return `<section class="dream-shop"><div class="shop-heading"><div><span class="eyebrow">YOUR MONEY, YOUR DREAMS</span><h2>당첨되면, 꼭 해보고 싶었던 것.</h2><p>말로만 하던 꿈을 이제 내 생활로 골라보세요.</p></div><div class="shop-cash"><span>지금 쓸 수 있는 돈</span><strong>${won(s.cash)}</strong></div></div><div class="era-curation"><div><span class="mini-label">${date(s.month)} / 그 시절 위시리스트</span><h3>${era.title}</h3><p>${era.text}</p><small>시대별 테마 큐레이션은 게임 설정입니다. 실제 유행·출시 연도의 기록은 아닙니다.</small></div><div class="era-curation-links">${era.ids.map(id=>{const q=quotePurchase(s,id);return `<button data-buy="${id}" ${q.disabled?'disabled':''}><b>${q.item.name}</b><small>${won(q.price)}</small></button>`;}).join('')}</div></div><nav class="shop-categories" aria-label="위시리스트 종류">${SHOP_CATEGORIES.map(c=>`<button data-shop-category="${c.id}" aria-pressed="${c.id===category.id}" class="${c.id===category.id?'active':''}">${c.name}</button>`).join('')}</nav><div class="shop-category-heading"><h3>${category.subtitle}</h3><span>${category.id==='home'?escape(REGIONS[s.region].name)+' 기준의 가상 주거 유형':'구체적인 물건·경험 유형 · 실제 브랜드 상품 아님'}</span></div><div class="product-grid">${items.map(item=>{const q=quotePurchase(s,item.id);return `<article class="product-card"><div class="product-art art-${item.type}">${productArt(item)}<span>${item.type==='home'?'HOME':item.type==='car'?'DREAM CAR':item.type==='luxury'?'COLLECTION':'MEMORIES'}</span></div><div class="product-body"><span class="product-tag">${item.tag}</span><h3>${item.name}</h3><p>${item.description}</p><div class="product-price">${won(q.price)}</div><div class="product-facts"><div><span>구매 부대비용</span><b>${won(q.fee)}</b></div><div><span>월 유지·관리비</span><b>${won(q.monthly)}</b></div><div><span>생활 만족</span><b>+${item.happy}</b></div></div>${q.credit?`<div class="trade-in">기존 차 정리 ${won(q.credit)} 반영</div>`:''}<button class="btn product-buy" data-buy="${item.id}" ${q.disabled?'disabled':''}>${q.disabled?escape(q.reason):item.type==='home'?'이 집에서 살기':item.type==='car'?(s.car?'이 차로 바꾸기':'이 차 타기'):item.type==='luxury'?'내 컬렉션에 담기':'이 여행 떠나기'} <span>↗</span></button></div></article>`;}).join('')}</div><p class="game-assumption">모든 상품은 게임용 유형입니다. 가격·거래비용·유지비·감가·중고 가치는 실제 매물이나 브랜드 시세가 아닙니다. 집은 지역의 가정 가격, 다른 상품은 가정 물가를 반영합니다.</p>${ownedCollection()}<button class="btn secondary spacer" data-tab="life">내 삶으로 돌아가기 →</button></section>`;}
function ownedCollection(){const s=state,collection=s.collection||[],memories=s.memories||[];if(!s.home&&!s.car&&!collection.length&&!memories.length)return `<section class="owned-section"><h3>나만의 보유 목록</h3><p>내가 고른 집과 차, 소장품과 여행의 기억이 이곳에 남습니다.</p></section>`;return `<section class="owned-section"><div class="section-heading"><h3>이제 나의 생활이 된 것들</h3><span class="eyebrow">MY OWN WORLD</span></div><div class="owned-grid">${s.home?`<article class="owned-card"><span class="mini-label">내 집</span><h4>${escape(s.homeDetails?.name||'거주 주택')}</h4><p>${escape(s.homeDetails?.tag||REGIONS[s.region].name)}</p><small>현재 평가액</small><b>${won(s.home)}</b><button class="text-button" data-action="house" ${s.ended?'disabled':''}>집 매도 · 평가액의 98% 회수</button></article>`:''}${s.car?`<article class="owned-card"><span class="mini-label">나의 차</span><h4>${escape(s.vehicle?.name||'기존 차량')}</h4><p>${escape(s.vehicle?.tag||'예전 단순 보유 기록')}</p><small>현재 중고 평가액</small><b>${won(s.vehicle?.value||0)}</b><button class="text-button" data-action="car" ${s.ended?'disabled':''}>차량 정리하기</button></article>`:''}${collection.map(x=>`<article class="owned-card"><span class="mini-label">소장품</span><h4>${escape(x.name)}</h4><p>${date(x.month)}에 내 컬렉션에 담았어요.</p><small>현재 중고 평가액</small><b>${won(x.value)}</b><button class="text-button" data-sell-owned="${x.id}" ${s.ended?'disabled':''}>정리하기 · 중고 가치의 95% 회수</button></article>`).join('')}${memories.slice(-6).reverse().map(x=>`<article class="owned-card memory"><span class="mini-label">경험과 추억</span><h4>${escape(x.name)}</h4><p>${date(x.month)}의 기록</p><small>당시 지출</small><b>${won(x.cost)}</b><span class="note">돈으로 다시 팔 수 없는 기억이에요.</span></article>`).join('')}</div></section>`;}
function purchaseReview(id){const q=quotePurchase(state,id);if(q.disabled)return toast(q.reason);const item=q.item,d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">MAKE IT PART OF YOUR LIFE</span><h2>${item.name}</h2></div><button class="close" data-close-purchase="true" aria-label="구매 확인 닫기">×</button></div><p class="purchase-description">${item.description}</p><div class="purchase-art">${productArt(item)}</div><div class="purchase-breakdown"><div><span>물건·경험 가격</span><b>${won(q.price)}</b></div><div><span>취득·등록 부대비용</span><b>${won(q.fee)}</b></div>${q.credit?`<div><span>기존 차량 정리 후 회수</span><b>− ${won(q.credit)}</b></div>`:''}<div class="purchase-total"><span>이번 현금 변화</span><b>${q.cost<0?'+ ':''}${won(-q.cost)}</b></div><div><span>구매 후 남는 현금</span><b>${won(state.cash-q.cost)}</b></div><div><span>월 지출 변화</span><b>${won(q.monthlyChange)}</b></div><div><span>생활 만족</span><b>+${item.happy} (최대 100)</b></div></div><p class="game-assumption">${item.type==='home'?'매매 부대비용 3%, 매도 시 2%를 가정합니다. 집은 1채만 거주용으로 보유합니다.':item.type==='car'?'등록 부대비용 7%와 감가상각을 가정합니다. 기존 차가 있으면 중고 평가액의 98%로 정리하고 새 차로 바꿉니다.':item.type==='luxury'?'중고 가치는 구매 가격보다 낮게 계산하며 시간이 지나면 줄어듭니다. 투자 수익을 가정하지 않습니다.':'여행비는 소비이며 재산으로 남지 않습니다. 대신 경험과 추억으로 기록합니다.'} 금액과 효과는 모두 게임 가정입니다.</p><div class="draw-actions"><button class="btn secondary" data-close-purchase="true">조금 더 둘러보기</button><button class="btn" data-confirm-purchase="${item.id}">${item.type==='home'?'내 집으로 선택':item.type==='car'?'나의 차로 선택':item.type==='luxury'?'내 것으로 만들기':'여행 떠나기'} ↗</button></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}


function worldPreview(){const l=lifestyle(state);return `<div class="world-preview"><div><span class="mini-label">MY OWN WORLD</span><b>${l.scenes.length?'구매한 꿈, 이제 첫 순간을 골라볼까요?':l.week<3?'당첨 첫 주의 설렘부터, 나의 공간까지.':'내가 고른 물건이 나의 하루가 되는 곳.'}</b><small>${l.moments.length}개의 기억 · ${l.rooms.length}개의 취향 공간</small></div><button class="btn secondary small" data-tab="world">${l.scenes.length?'첫 순간 선택하기':'나의 공간 열기'} ↗</button></div>`;}
function lifeReview(kind,id){const q=quoteLife(state,kind,id);if(q.disabled)return toast(q.reason);const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">MAKE YOUR EVERYDAY</span><h2>${escape(q.item.name)}</h2></div><button class="close" data-close-purchase="true" aria-label="선택 확인 닫기">×</button></div><p>${escape(q.item.detail)}</p><div class="purchase-breakdown"><div><span>이번 지출</span><b>${won(q.cost)}</b></div><div><span>이후 현금</span><b>${won(state.cash-q.cost)}</b></div><div><span>월 기본 생활비 변화</span><b>${won(q.monthlyChange)}</b></div><div><span>생활 만족 변화</span><b>+${q.item.happy||0} (최대 100)</b></div></div><p class="game-assumption">금액과 효과는 게임 가정입니다. 꾸미기·지원·체험 비용은 소비이며 재산으로 남지 않습니다. 가족 지원의 증여세는 미반영이고 관계 개선을 자동으로 보장하지 않습니다. 시간은 자동으로 진행되지 않습니다.</p><div class="draw-actions"><button class="btn secondary" data-close-purchase="true">돌아가기</button><button class="btn" data-life-confirm="${kind}:${id}">내 일상에 담기 →</button></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}


function moveReview(region){const q=moveQuote(state,region);if(q.disabled)return toast(q.reason);const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">A NEW EVERYDAY</span><h2>${escape(REGIONS[region].name)}으로 이사</h2></div><button class="close" data-close-purchase="true" aria-label="이사 확인 닫기">×</button></div><div class="purchase-breakdown"><div><span>이사 비용</span><b>${won(q.cost)}</b></div><div><span>이사 후 현금</span><b>${won(state.cash-q.cost)}</b></div><div><span>새 월세</span><b>${won(q.rent)}</b></div><div><span>월 지출 변화</span><b>${won(q.monthlyChange)}</b></div></div><p class="game-assumption">이사비·월세·지역별 집값은 게임 가정입니다. 실제 매물과 보증금은 미반영이고 직장·급여는 그대로입니다. 지역을 바꿨다는 이유로 만족·건강 보너스를 주지 않습니다.</p><div class="draw-actions"><button class="btn secondary" data-close-purchase="true">돌아가기</button><button class="btn" data-move-confirm="${escape(region)}">이 지역에서 시작하기 →</button></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}


function tradeReview(id,side,all=false){const a=MARKET_BY_ID[id];if(!a)return toast('매매 대상을 확인해 주세요.');const d=document.createElement('dialog');d.className='purchase-dialog trade-dialog';d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">IF EXCHANGE / ${a.symbol}</span><h2>${escape(a.name)} ${side==='buy'?'매수':'매도'}</h2></div><button class="close" data-close-purchase="true" aria-label="매매 확인 닫기">×</button></div><p>${escape(a.description)}</p><form id="trade-form"><label class="field">${all?'보유 자산 전량 매도':side==='buy'?'투입할 원화 예산':'매도할 원화 평가액'}<input name="tradeAmount" type="text" inputmode="numeric" value="10,000,000" ${all?'readonly':''}><small>${all?'현재 보유 수량 전부를 확인합니다.':'10,000원 이상 · 매수 예산에 수수료 포함 / 매도 회수금은 수수료 차감'}</small></label>${all?'':`<div class="trade-presets">${[1000000,10000000,100000000].map(n=>`<button type="button" data-amount="${n}">${won(n)}</button>`).join('')}</div>`}<div id="trade-breakdown" class="purchase-breakdown" aria-live="polite"></div><div id="trade-error" class="form-error" role="alert"></div><p class="game-assumption">모형 가격과 수수료 ${(a.fee*100).toFixed(1)}%를 적용합니다. 실제 주문이 아니며 세금은 미반영입니다. 매매해도 날짜는 진행되지 않습니다.</p><div class="draw-actions"><button class="btn secondary" type="button" data-close-purchase="true">돌아가기</button><button class="btn" type="submit">${side==='buy'?'매수':'매도'} 확정 →</button></div></form>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());const form=d.querySelector('form'),input=form.elements.tradeAmount;function quote(){try{const q=quoteTrade(state,id,side,all?0:parseMoneyInput(input.value),all);if(all)input.value=q.gross.toLocaleString('ko-KR');d.querySelector('#trade-error').textContent=q.reason;d.querySelector('button[type="submit"]').disabled=q.disabled;d.querySelector('#trade-breakdown').innerHTML=`<div><span>현재 단위 가격</span><b>${won(q.price)} / ${a.unit}</b></div><div><span>${side==='buy'?'매수':'매도'} 수량</span><b>${q.units.toLocaleString('ko-KR',{maximumFractionDigits:6})}${a.unit}</b></div><div><span>평가 금액</span><b>${won(q.gross)}</b></div><div><span>수수료</span><b>${won(q.fee)}</b></div><div><span>${side==='buy'?'현금 지출':'현금 회수'}</span><b>${won(q.cash)}</b></div><div><span>이후 현금</span><b>${won(state.cash+(side==='buy'?-q.cash:q.cash))}</b></div>`;applyReadability(d.querySelector('#trade-breakdown'));}catch(error){d.querySelector('#trade-error').textContent=error.message;d.querySelector('button[type="submit"]').disabled=true;}}input.addEventListener('input',()=>{const digits=input.value.replaceAll(',','');if(/^\d+$/.test(digits)&&Number.isSafeInteger(Number(digits)))input.value=Number(digits).toLocaleString('ko-KR');quote();});d.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>{input.value=Number(b.dataset.amount).toLocaleString('ko-KR');quote();}));form.addEventListener('submit',ev=>{ev.preventDefault();try{trade(state,id,side,all?0:parseMoneyInput(input.value),all);save();d.close();tab='market';render();toast('보유 수량과 현금, 수수료를 장부에 반영했어요.');}catch(error){d.querySelector('#trade-error').textContent=error.message;}});applyReadability(d);quote();}

function assets(){const s=state;return `<div class="finance-grid"><section class="stack"><div class="card"><div class="section-heading"><h3>나의 자산 장부</h3><span class="mini-label">${date(s.month)}</span></div>${[['시장 자산',marketValue(s),'달러·금·IF 테마 주식의 모형 평가액'],['현금',s.cash,'바로 사용할 수 있는 돈'],['예금',s.deposit,`가정 연 이자율 ${(gameEconomy(s).deposit*100).toFixed(1)}% · 이자는 현금으로 지급`],['분산 주식',s.stocks,'실제 종목이 아닌 가상 지수'],['거주 주택',s.home,s.homeDetails?.name||'가정된 시장 평가액'],['보유 차량',s.vehicle?.value||0,s.vehicle?.name||'차량 없음 또는 예전 단순 기록'],['소장품',(s.collection||[]).reduce((sum,x)=>sum+x.value,0),'중고 가치의 게임 가정'],['생활비 부족분',-s.debt,'현금이 모자라면 누적 · 이자는 미반영'],['순자산',worth(s),'보유 자산 합계에서 부족분 차감']].map(([name,value,note])=>`<div class="asset-row"><div><b>${name}</b><small>${note}</small></div><b>${won(value)}</b></div>`).join('')}</div><div class="card"><h3>수입과 지출</h3>${flows()}<p class="note spacer">집 구매 시 거래비용 3%, 매도 시 2%를 가정합니다. 구체적으로 고른 차량과 명품은 중고 가치를 계산합니다. 예전 단순 차량 기록은 잔존가치 0원입니다.</p></div></section><section><div class="section-heading"><h3>생활과 자산 관리</h3><span class="eyebrow">${s.ended?'기록이 완료되었어요':'현재 보유 현금으로 실행'}</span></div><div class="shop-link-row"><button class="btn secondary" data-shop="home">집 고르기 ↗</button><button class="btn secondary" data-shop="car">차 고르기 ↗</button><button class="btn secondary" data-shop="luxury">명품 고르기 ↗</button></div><div class="actions-grid">${availableActions(s).filter(a=>!['house','car',...(s.market?['invest','sell']:[])].includes(a.id)).map(a=>`<button class="action-card" data-action="${a.id}" ${a.disabled?'disabled':''}><b>${a.title} <span>↗</span></b><small>${escape(a.detail)}</small></button>`).join('')}</div><div class="game-assumption">가격·급여·사업손익·물가·수익률은 모두 게임 가정입니다. 실제 지역별 거래 가격이나 역사 수익률을 재현한 것이 아닙니다.</div><p class="note">집·차·명품은 위시리스트에서 직접 고를 수 있습니다. 보유 물건과 유지비도 함께 확인해 주세요.</p><button class="btn secondary spacer" data-tab="life">나의 삶으로 돌아가기 →</button></section></div>`;}
function journal(){const logs=state.log.filter(l=>filter==='all'||(filter==='choice'?['choice','purchase','action','result'].includes(l.type):l.type===filter));return `<div class="ledger-tools"><div><h2 style="margin:0;font-size:22px">선택은 기록이 된다.</h2><p class="note" style="margin:4px 0">${state.log.length}개의 기록 · 이 브라우저에 자동 저장${storageOK?'됨':' 불가'}</p></div><div class="utility"><button class="btn secondary small" data-ui="export">기록 내려받기</button><button class="btn secondary small" data-ui="import">불러오기</button><button class="text-button" data-ui="new">새 삶 시작</button></div></div><div class="ledger-tools"><label for="log-filter" class="quiet">기록 종류</label><select id="log-filter"><option value="all" ${filter==='all'?'selected':''}>전체 기록</option><option value="choice" ${filter==='choice'?'selected':''}>선택과 결과</option><option value="news" ${filter==='news'?'selected':''}>사건</option><option value="month" ${filter==='month'?'selected':''}>월별 가계부</option></select></div><div class="card full-journal">${logs.length?logs.slice().reverse().map(l=>`<article class="journal-card"><span class="journal-tag">${date(l.month)} · ${{start:'시작',choice:'내 선택',purchase:'꿈 실현',action:'생활 선택',result:'추후 결과',month:'월별 가계부',news:'사건'}[l.type]||'기록'}</span><h3>${escape(l.title)}</h3><p>${escape(l.text)}</p></article>`).join(''):'<p class="empty-state">아직 이 종류의 기록은 없어요.</p>'}</div>`;}
function summary(){const s=state,net=income(s)-expenses(s)-loanDue(s);return `<article class="summary-hero"><div class="eyebrow" style="color:#a9bdcf">THIS IS YOUR IF</div><h2 class="spacer">${s.name?escape(s.name)+'의':''}<br>또 다른 오늘에 도착했다.</h2><p>${escape(s.reason)}</p><div class="summary-grid"><div><div class="note">최종 순자산</div><div class="value">${won(worth(s))}</div></div><div><div class="note">시작 물가 기준 구매력</div><div class="value">${won(worth(s)/s.cpi)}</div></div><div><div class="note">현금 + 예금으로 버틸 기간</div><div class="value">${net>=0?'월 적자 없음':((s.cash+s.deposit)/-net/12).toFixed(1)+'년'}</div></div></div><p class="note spacer">기간은 현재 월 적자가 유지된다는 가정이며, 향후 물가·수익률 변화와 자산 매각은 반영하지 않았습니다.</p><div class="utility"><button class="btn lime" data-ui="export">이 삶의 기록 보관하기</button><button class="btn secondary" style="color:#fff;border-color:#555" data-ui="new">다른 삶 시작하기</button></div></article>${renderLifeAlbum(s,{escape,won,date})}`;}
function docs(){return `<section class="docs"><div class="notice"><b>경제사를 삶과 선택으로 배우는 학습 시뮬레이션입니다.</b><br>1~1,245회 자료를 내장했습니다. 공식 원본 전체 대조는 미완료입니다. 당시 세금·실제 경제 시계열은 아직 연결하지 않았습니다. 검증되지 않은 가격을 실제 자료처럼 제시하지 않습니다.</div><h2>경제 시장과 실제 역사 가격의 차이</h2><p>현금·예금·달러·금·분산 지수와 7개 테마 주식을 사용할 수 있습니다. 종목은 IF 가상 주식이며 실제 회사나 실제 주가가 아닙니다. 원/달러 환율, 금 가격, 주가, 원화 예금금리, 수익률과 사건의 충격 크기는 모두 게임 모형입니다. 사건의 날짜·사실만 1차 출처로 확인했습니다. 실제 경제 시계열은 아직 연결하지 않았습니다.</p><p>월 기본 변동은 날짜·자산별 고정 규칙으로 계산하고, 사건 충격은 해당 월에 한 번 적용합니다. 같은 사건을 다시 확인하거나 저장을 불러와도 충격을 재적용하지 않습니다. 기존 연도별 주식 수익률과 시장 사건 충격을 중복으로 더하지 않습니다. 새 모형의 예금금리·물가·주택 연율을 사용합니다. 미국·영국 정책금리가 원화 예금금리와 같다고 가정하지 않습니다. 금의 원화 가격은 모형 달러/g 가격 × 모형 원/달러 환율입니다.</p><p>당첨금은 원화로 받은 뒤 선택한 시작 구성으로 나눕니다. 처음부터 외화나 금으로 당첨금을 지급하는 설정은 아닙니다. 매매 수수료는 주식 0.2%, 달러 0.4%, 금 0.5%이고 세금·공매도·레버리지·배당·외화 이자·금 보관비는 미반영입니다. 예금은 변동 금리이며 월별 이자를 현금으로 지급합니다. 초기 배분에도 수수료가 발생합니다.</p><p>시작 월의 가격은 그달 사건을 포함한 월말 모형 기준입니다. 시작일 전후의 실제 일 단위 시장 시점은 재현하지 않습니다. 시작 월 사건으로 당첨금에 소급 손익을 부과하지 않습니다. 이후에는 그달 시장 변동을 먼저 계산하고 사건을 순서대로 확인합니다. 이미 발생한 손익을 사건 확인 뒤의 매매로 되돌릴 수 없습니다. 현재 이후 반년마다 나타나는 시장 사건은 가상 미래 시나리오입니다.</p><p>대통령 취임과 실제 정책 발표를 구분합니다. 균형발전·녹색성장·창조경제·일자리·민간 투자·첨단 산업 등의 발표 방향을 정책 시나리오로 연결합니다. 대통령이나 정당에 따른 자동 현금 보상·벌점은 없습니다. 산업 반응·대외 경기 노출·모형 금융 환경의 계수는 실제 인과효과를 추정한 값이 아닌 게임 가정입니다. 정책 방향은 최대 60개월의 시나리오로 다음 달부터 월 변동에 반영되며 다음 발표가 기존 방향을 교체합니다. 현재 정부·재임 기간의 완전한 재현은 아닙니다.</p><h3>경제 사건 출처</h3><ul class="source-list">${MARKET_EVENTS.filter(e=>!state?.learning||e.month<=state.month).map(e=>`<li><a href="${escape(e.url)}" target="_blank" rel="noopener noreferrer">${e.date} · ${escape(e.title)} ↗</a><small>${escape(e.source)} · 가격 반응·예금금리는 별도 게임 가정</small></li>`).join('')}</ul><h2>사실과 가정을 분리합니다.</h2><table><thead><tr><th>구분</th><th>현재 반영한 내용</th></tr></thead><tbody><tr><td>역사적 사실</td><td>출처가 있는 사건 5개의 발생 시기와 사실 관계</td></tr><tr><td>사용자 설정</td><td>시작 월·회차 이름·세전 금액·실제 또는 가정 수령액</td></tr><tr><td>게임 가정</td><td>집값·월세·물가·급여·예금 금리·주식 수익률·사업 손익·선택의 효과</td></tr><tr><td>미반영</td><td>전 회차 공식 원본 대조, 당시 세법, 증여세·소득세·보유세, 대출 심사·이자, 개인별 건강·사업 성공 확률</td></tr></tbody></table><h2>경제 계산은 이렇게 작동해요.</h2><ul><li>매월 급여·사업손익·예금 이자를 현금에 반영하고 생활·주거비를 차감합니다.</li><li>예금과 주식 매수는 자산 이동입니다. 주식과 주택은 가정된 수익률에 따라 평가액이 변합니다.</li><li>물가 배율은 시작 시점을 1로 두고 매월 누적합니다. 구매력은 순자산 ÷ 물가 배율로 표시합니다.</li><li>연 물가·주식·주택 변동률은 월 복리로 환산합니다. 금리는 게임상 세후 수령 이자율로 간주합니다.</li><li>정치 사건에 정치적 성향에 따른 금전 보상·능력치 벌점은 부여하지 않습니다.</li><li>생활비 부족분은 자동 누적되고 이후 현금으로 상환합니다. 예전 역사 모드는 부족분 5,000만 원이면 종료됩니다. 새 생애 모드는 생활비 부족으로 즉시 종료하지 않고 삶을 계속합니다. 자산은 자동 매각하지 않으므로 현금 관리가 필요합니다.</li><li>한 번에 1년을 진행해도 선택할 사건이 발생하면 그 달에 멈춥니다. 시작 이전 사건은 나오지 않습니다.</li><li>새 삶은 75세 이후 매년 16%의 종료 확률을 가정하고 100세 전에 마칩니다. 실제 수명 예측이 아니며 성별 차이는 없습니다. 현재 구현한 건강·만족 효과는 단순 게임 지표이며, 개인 사건은 3개월마다 상황에 맞게 등장합니다. 14개 유형을 순환하며 여행 사건은 게임의 감염병 영향 기간에는 제외합니다.</li></ul><h2>달력으로 당첨 시점 고르기</h2><p>회차를 직접 고르거나 구매 날짜·시간을 달력에서 고를 수 있습니다. 일~금 06:00~24:00, 토요일 06:00~20:00를 적용합니다. 마감 시각부터는 구매하지 못하는 것으로 처리합니다. 평일이나 일요일을 고르면 그다음 토요일 추첨 회차에 연결됩니다. 인생은 복권 구매일이 아니라 당첨일에서 시작합니다. 이 판매시간을 과거 전체에 동일하게 적용하는 게임 규칙입니다. 1,245회 이후 미추첨 날짜의 당첨번호는 만들지 않습니다.</p><a class="source" href="https://www.dhlottery.co.kr/lt645/intro" target="_blank" rel="noopener noreferrer">동행복권 판매시간 안내 ↗</a><h2>위시리스트와 내가 고른 생활</h2><p>집 5종, 차 6종, 명품·취향 5종, 여행 3종을 직접 고릅니다. 구매 확인창에서 가격·취득 및 등록비·차 교체 시 회수액·남는 현금·월 지출 변화를 확인합니다. 고른 물건과 경험은 보유 목록과 기록에 남습니다.</p><p>집은 지역별 가정 가격의 배율을 사용하고 차량·명품·여행은 2020년 기준의 가정 가격과 게임 물가를 적용합니다. 실제 매물·브랜드 모델·실제 출시일의 재현은 아닙니다. 전기 SUV의 2016년 개방도 게임 규칙입니다. 자동차는 등록비 7%와 감가를 가정하며 기존 차를 평가액의 98%로 정리한 뒤 교체합니다. 집은 거주용 1채를 보유합니다. 명품 중고 가치는 품목별 비율로 시작해 줄어들고 매도 시 5%를 차감합니다. 여행은 지출이며 월 1회 경험으로 기록됩니다. 모든 비용·중고 가치·만족 효과는 게임 가정입니다.</p><h2>내 선택의 다음 장</h2><p>퇴사 이후의 휴식·새 목표·다시 일하기, 집·차·꾸민 방·취미·가족 지원·여행 이후의 분기 이야기가 이어집니다. 역사 사건은 같은 달에 우선 표시됩니다. 후속 이야기는 다음 달 또는 두 달 뒤부터 준비되며, 이전 선택에 따라 다음 장이 달라집니다. 각 장은 한 번만 등장하고 관련 물건을 처분하면 아직 만나지 않은 이야기가 취소됩니다. 비용·만족·근로소득 재개는 게임 규칙입니다. 시간의 방향은 준비된 이야기 우선순위만 바꾸며 실제 시간 배분이나 근로시간을 계산하지 않습니다. 지역 이사는 자가를 먼저 매도한 뒤 월 1회 가능합니다. 새 월세·이사비는 가정이며 보증금·직장 이전·세금은 미반영입니다. 주택 보유 기간은 이 기능이 추가된 뒤의 구매부터 기록하며, 기존 저장의 과거 기간을 추정하지 않습니다.</p><h2>나의 공간과 추억</h2><p>당첨 첫 주는 날짜를 진행하지 않는 세 장면의 회상입니다. 집·차·소장품·여행 구매 뒤에는 첫 순간을 선택해 추억으로 남깁니다. 내 집에서는 서재·홈시네마·게임과 음악의 방·손님방을 한 번씩 꾸밀 수 있습니다. 실제 평면이나 방 개수의 재현은 아닙니다. 집 매도 시 꾸민 방은 사라지지만 추억은 남습니다. 가족 지원과 취미 수업은 월 1회입니다. 가족 구성이나 관계 개선을 자동으로 가정하지 않습니다. 버킷리스트는 실제 행동에 따라 완료됩니다. 생활 수준 변경은 기준 생활비의 배율이며 주거·차량 유지비는 별도입니다. 모든 금액과 효과는 게임 가정입니다.</p><h2>거주 지역</h2><p>지역 선택지는 85곳입니다. 특별시·광역시·특별자치시와 도 아래의 시, 제주 행정시를 포함합니다. 행정안전부 2024.12.31 현황을 기준으로 시·도별로 묶고 각 그룹 안에서 인구순으로 정렬했습니다. 선택 화면에는 인구 숫자를 표시하지 않습니다. 군과 구는 선택지에 넣지 않았습니다. 과거와 이후의 행정구역 개편 및 인구 변화는 미반영입니다. 집값·월세는 실제 통계가 아닌 게임 설정입니다.</p><a class="source" href="https://www.mois.go.kr/frt/bbs/type001/commonSelectBoardArticle.do?bbsId=BBSMSTR_000000000055&nttId=118777" target="_blank" rel="noopener noreferrer">행정안전부 지역·인구 자료 ↗</a><h2>역대 최고 당첨금으로 시작하기</h2><p>제19회는 2003년 4월 12일 추첨에서 1등 1게임에 세전 40,722,959,400원을 지급한 최고 기록입니다. 내장 1~1,245회 데이터에서도 1게임당 1등 당첨금이 가장 큽니다. 직전 제18회의 당첨금이 이월된 배경이 있습니다. 이데일리 보도에 실수령액은 약 31,763,900,000원으로 기재되어 있어, 제19회 기존 당첨자 규칙의 기본 수령액으로 사용합니다. 보도된 근사치이며 전체 회차의 당시 세법을 계산하는 기능은 아닙니다. 자료를 수정하거나 플레이어 추가 규칙을 고르면 기존 70% 임시 가정을 적용합니다.</p><a class="source" href="https://www.edaily.co.kr/News/Read?mediaCodeNo=257&amp;newsId=01308726609272488" target="_blank" rel="noopener noreferrer">이데일리 · 제19회 최고 당첨금과 실수령액 보도 ↗</a><h2>로또 회차와 수명</h2><p>내장 자료는 1~1,245회입니다. 민간 API의 날짜·번호·인원·상금 자료를 확보했고 1~1,156회는 별도 데이터 사본과 비교해 일치했습니다. 1,157~1,245회는 단일 공급처 자료입니다. 공식 원본 전체 대조는 아직 필요합니다.</p><p>기존 당첨자 한 명이 플레이어였다고 가정하면 기록된 1인당 상금을 사용합니다. 플레이어를 추가하면 총 배정액을 늘어난 인원으로 다시 나눕니다. 1회처럼 당첨자가 없는 회차는 가상 당첨자 1명에게 입력 배정액을 지급합니다. 1회에는 데이터 사본 배정액 863,604,600원을 적용합니다. 당시 기사 배정액 863,608,600원과 4,000원 차이가 있어 재검증이 필요합니다. 또한 당시 최저당첨금 보증은 미반영입니다.</p><p>수령액 70%는 임시 가정입니다. 새 삶은 생성 시 종료 나이를 한 번 추첨해 저장하며, 75세 이후 매년 16%의 조건부 종료 확률과 100세 상한을 적용합니다. 시작 나이가 75세 이상이면 다음 생일부터 적용합니다. 75세 미만 시작 시 평균 종료 나이는 약 80.2세입니다. 성별과 건강 지표는 수명에 영향을 주지 않습니다. 현재 이후는 가상 미래이며 경제 가정을 계속 적용합니다.</p><h2>위키 자료를 시장에 반영하는 순서</h2><ol><li>위키에서 사건 날짜와 핵심 사실을 추출하고 원문 URL을 보관합니다. 위키의 표현을 그대로 옮기지 않습니다.</li><li>주요 사건은 정부·통계·당시 보도 등으로 날짜와 사실 관계를 확인합니다.</li><li>금리·물가·환율·고용·부동산 등 어떤 경로에 영향을 주는지 정리합니다. 수치가 없으면 ‘게임 가정’으로 표시합니다.</li><li>실제 경제 시계열을 쓰는 경우 이미 반영된 변화에 사건 효과를 다시 더하지 않습니다. 서사 이벤트와 가격 계산을 구분합니다.</li></ol><p>현재는 새 위키 사건을 자동 수집하거나 임의 시장 충격으로 연결하는 기능이 없습니다. 자료를 제공하면 검증과 조정을 거쳐 사건 데이터로 확장할 수 있습니다.</p><h2>역사 사건의 출처</h2><ul class="source-list">${HISTORIES.filter(h=>!state?.learning||h.month<=state.month).map(h=>`<li><a href="${escape(h.url)}" target="_blank" rel="noopener noreferrer">${h.date} · ${escape(h.title)} ↗</a><small>${escape(h.source)} · 사건의 사실과 날짜만 사용. 선택 효과는 별도 게임 가정.</small></li>`).join('')}</ul><h2>〈IF 세계〉 제작 순서</h2><ol><li>현재 단계: 생활 장부·선택 카드·시간 진행·저장 가능한 플레이 구조를 검증합니다.</li><li>동행복권 회차·날짜·1인당 당첨금 자료를 수집하고 원본 출처와 누락 여부를 확인합니다. 당첨자가 없는 회차는 별도 규칙이 필요합니다.</li><li>시기별 세법·소비자물가·금리·지역별 주택 자료를 검증하고 경제 가정을 하나씩 실제 시계열로 교체합니다.</li><li>정치·경제·사회문화 사건을 날짜·출처·영향 대상 기준으로 확장합니다.</li><li>인물·직업·가족 상황에 따른 사건, 장기 결과, 확률과 난이도를 조정합니다.</li><li>다른 선택의 삶 비교, 모바일 플레이 검증, 전체 회차 확장을 진행합니다.</li></ol><p>학습 화면에서는 준비 선택 전 미래 사건명과 가격을 공개하지 않고, 현재 월까지의 타임라인과 출처를 보여줍니다. 플레이어가 이미 알고 있는 미래를 차단할 수는 없어요.</p></section>`;}
function setup(initialId='400'){
 const initialRound=initialId==='2008'||initialId==='2017'||initialId==='2020'?400:Number(initialId)||400;
 const d=document.createElement('dialog');d.id='setup';
 d.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">01 PERSON / 02 ROUND / 03 DRAW</div><h2>당신의 시작을 고르세요.</h2></div><button class="close" data-ui="close" aria-label="설정 닫기">×</button></div><form id="setup-form"><div class="setup-section"><span class="setup-step">01</span><h3>그때의 당신</h3><div class="form-grid"><label class="field">이름<input name="name" maxlength="20" value="여행자" required></label><label class="field">당첨 당시 나이<input name="age" type="number" min="19" max="80" value="28" required></label><label class="field">성별<select name="gender"><option value="male">남성</option><option value="female">여성</option><option value="unspecified">선택하지 않음</option></select></label><label class="field">거주 지역<select name="region">${REGION_GROUPS.map(group=>`<optgroup label="${escape(group.name)}">${group.regions.map(key=>`<option value="${escape(key)}" ${key==='incheon'?'selected':''}>${escape(REGIONS[key].city)}</option>`).join('')}</optgroup>`).join('')}</select><small>시 단위 85곳 · 인구가 많은 순서</small></label></div><p class="note">지역 목록은 2024년 말 기준입니다. 과거·이후 행정구역 개편은 미반영입니다. 집값·월세는 게임 가정입니다.</p><p class="note">75세 이후 매년 16%의 종료 확률을 가정하며 100세가 상한입니다. 성별별 수명 차이는 미반영입니다. 실제 수명 통계가 아닌 평균 약 80세의 게임 규칙입니다.</p></div><div class="setup-section"><span class="setup-step">02</span><h3>당첨될 회차</h3><div class="round-shortcuts"><button type="button" data-round-preset="1">1회 · 첫 추첨</button><button type="button" data-round-preset="19">19회 · 역대 최고액</button><button type="button" data-round-preset="1245">1,245회 · 최신</button><button type="button" id="import-lottery">회차 자료 JSON 불러오기 ↗</button></div><input type="file" id="lottery-file" accept=".json,application/json" hidden><div class="selection-modes" role="group" aria-label="시작점 선택 방식"><button type="button" data-selection-mode="round" class="active" aria-pressed="true">회차로 고르기</button><button type="button" data-selection-mode="calendar" aria-pressed="false">달력으로 고르기</button></div><div id="calendar-mode-panel" hidden><div class="form-grid"><label class="field">복권을 사는 날짜<input name="purchaseDate" type="date" min="2002-12-07" max="2026-10-12"></label><label class="field">구매 시간 · 한국시간<input name="purchaseTime" type="time" value="12:00" step="60"></label></div><div id="calendar-hint" class="calendar-hint" aria-live="polite"></div><p class="note">일~금 06:00~24:00 / 토요일 06:00~20:00. 마감 시각부터는 구매할 수 없습니다. 판매시간을 전 기간에 동일하게 적용하는 게임 기준입니다.</p></div><div class="form-grid" id="round-mode-panel"><label class="field">로또 회차<input name="roundNumber" type="number" list="round-list" min="1" max="${latestRound()}" value="${initialRound}" required></label><label class="field">실제 추첨일<input name="drawDate" type="date" min="2002-12-07" max="2026-10-12" required></label></div><datalist id="round-list">${CATALOG.map(r=>`<option value="${r.round}">${date(r.date)} · 1등 ${r.winners}명</option>`).join('')}</datalist><div id="round-info" class="round-info" aria-live="polite"></div><details class="round-details"><summary>회차 자료 확인·수정 <span>+</span></summary><div class="form-grid"><label class="field" style="grid-column:1/-1">당첨번호 6개<input name="numbers" placeholder="예: 9,21,27,34,41,43" required></label><label class="field">보너스 번호<input name="bonus" type="number" min="1" max="45" required></label><label class="field">실제 1등 당첨자 수<input name="winners" type="number" min="0" max="100000" required></label><label class="field">실제 1인당 세전 당첨금 (원)<input name="perWinner" type="text" inputmode="numeric" min="0" max="1000000000000" step="1" required></label><label class="field">1등 총 배정액 / 가상 지급액 (원)<input name="pool" type="text" inputmode="numeric" min="0" max="100000000000000" step="1" required><small>당첨자가 없는 회차의 시작 금액 기준</small></label></div></details><label class="field spacer">플레이어 당첨 규칙<select name="policy"><option value="replace">기존 당첨자 한 명이 나였다고 가정</option><option value="add">나를 추가하고 총 배정액을 다시 나누기</option></select><small>실제 당첨자가 0명이면 가상 당첨자 1명으로 처리합니다.</small></label><div class="form-grid spacer"><label class="field">사용할 세전 당첨금 (원)<input name="gross" type="text" inputmode="numeric" readonly required></label><label class="field">설정 수령액 (원)<input name="net" type="text" inputmode="numeric" min="1" step="1" required><small id="net-assumption">기본 70%는 임시 가정 · 당시 세금 계산 미연결</small></label></div><label class="field spacer">가정환경<select name="householdMode"><option value="manual">직접 설정 · 기본 가계</option><option value="random">무작위 · 15/25/35/20/5 게임 배정</option></select><small>무작위는 재산·기존 부채·급여·주거를 배정합니다. 실제 계층 비율이 아닙니다. 로또 당첨금은 별도로 더하며, 출생 모드에서는 입력한 시작 자산을 대신합니다.</small></label><label class="field spacer">난이도 · 시작 후 변경 불가<select name="difficulty"><option value="normal">보통 · 통계 사기·가상 의료비</option><option value="hard">어려움 · 가상 위기 연습 추가</option></select><small>2024년 사기 피해율 연결 · 다른 연도 미연결. 의료비·어려움의 추가 사건은 실제 발생률이 아닌 가상 연습입니다.</small></label><label class="field spacer">처음 자금 구성<select name="allocation">${ALLOCATIONS.map(p=>`<option value="${p.id}" ${p.id==='balanced'?'selected':''}>${p.name}</option>`).join('')}</select><small>여러 자산: 현금 약 40% · 예금 20% · 달러 10% · 금 10% · 분산 주식 20%. 실제 매수 수수료가 차감됩니다. 다른 구성도 이후 시장에서 자유롭게 바꿀 수 있습니다.</small></label><div class="game-assumption">1~1,245회 전체 자료가 들어 있습니다. 회차를 고르면 날짜·번호·당첨자·상금이 자동으로 표시됩니다. 1~1,156회는 두 사본을 대조했습니다. 최근 89회는 민간 API 자료이며 공식 원본 대조가 필요합니다. 일반 회차 수령액 70%와 지역별 주거비는 게임 가정입니다. 제19회 기존 당첨자 규칙은 보도된 실수령액 약 31,763,900,000원을 기본값으로 사용합니다.</div></div><div class="form-error" id="form-error" role="alert"></div><div class="form-footer"><span class="note">${saved?'새 삶은 저장 슬롯을 덮어씁니다.<br>기존 기록을 먼저 내려받아 주세요.':'추첨 연출 후 인생이 시작됩니다.'}</span><button class="btn" type="submit">03 · 당첨의 순간으로 →</button></div></form>`;
 document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());
 const form=d.querySelector('form'),field=n=>form.elements[n];let activeSource='',activeStatus='',selectionMode='round';
 function updateMoneyHints(){for(const name of ['perWinner','pool','gross','net']){const input=field(name);let hint=input.parentElement?.querySelector('.money-input-hint');if(!hint&&input.parentElement){hint=document.createElement('small');hint.className='money-input-hint';input.parentElement.append(hint);}if(hint){try{const n=parseMoneyInput(input.value);hint.textContent=moneyApprox(n)?'('+moneyApprox(n)+')':'';}catch{hint.textContent='';}}}}
 function record(){return validateRecord({round:Number(field('roundNumber').value),date:field('drawDate').value,numbers:field('numbers').value,bonus:Number(field('bonus').value),winners:Number(field('winners').value),perWinner:parseMoneyInput(field('perWinner').value),pool:parseMoneyInput(field('pool').value),source:activeSource,status:activeStatus});}
 function updatePrize(){try{const r=record(),prize=playerPrize(r,field('policy').value);field('gross').value=prize.gross.toLocaleString('ko-KR');const reported19=r.round===19&&r.date==='2003-04-12'&&r.winners===1&&r.perWinner===40722959400&&field('policy').value==='replace';field('net').value=(reported19?31763900000:Math.round(prize.gross*.7)).toLocaleString('ko-KR');d.querySelector('#net-assumption').textContent=reported19?'제19회 보도 실수령액 약 317.64억 원 · 근사치, 직접 수정 가능':'기본 70%는 임시 가정 · 당시 세금 계산 미연결';updateMoneyHints();d.querySelector('#round-info').innerHTML=`<b>제${r.round}회 · ${date(r.date)}</b><div class="round-balls">${r.numbers.map(n=>`<span class="lotto-ball ball-${Math.ceil(n/10)}">${n}</span>`).join('')}<span class="bonus-plus">+</span><span class="lotto-ball bonus-ball">${r.bonus}</span></div><p>실제 1등 ${r.winners}명 · 게임 속 ${prize.simulatedWinners}명<br>세전 ${won(prize.gross)}${r.winners===0?' · 실제 당첨금이 아닌 가상 지급액':''}</p><small>${escape(activeStatus)}${activeSource?` · <a href="${escape(activeSource)}" target="_blank" rel="noopener noreferrer">출처 ↗</a>`:''}</small>${lotteryRecords.get(r.round)?.poolNote?`<p class="data-discrepancy">${escape(lotteryRecords.get(r.round).poolNote)}</p>`:''}${reported19?'<p>1게임당 세전 1등 당첨금 역대 최고 회차입니다. 직전 제18회의 당첨금이 이월됐습니다.</p><small><a href="https://www.edaily.co.kr/News/Read?mediaCodeNo=257&amp;newsId=01308726609272488" target="_blank" rel="noopener noreferrer">최고 당첨금·실수령액 보도 ↗</a></small>':''}${r.winners===0?'<div class="zero-winner">실제로는 1등이 없어 이월된 회차입니다. 해당 회차 사본의 배정액을 가상 상금으로 적용하며 당시 최저당첨금 보증 규칙은 미반영입니다. 아래에서 금액을 바꿀 수 있어요.</div>':''}`;}catch(error){field('gross').value='';field('net').value='';updateMoneyHints();d.querySelector('#round-info').innerHTML=`<b>회차 자료 입력이 필요합니다.</b><p>${escape(error.message)}</p>`;}applyReadability(d.querySelector('#round-info'));}
 function loadRound(){const round=Number(field('roundNumber').value);try{field('drawDate').value=weeklyDate(round);}catch{field('drawDate').value='';}const r=lotteryRecords.get(round);activeSource=r?.source||'';activeStatus=r?.status||'사용자 입력 · 날짜는 정규 주간 일정 계산, 실제 추첨일 재확인 필요';for(const key of ['numbers','bonus','winners','perWinner','pool'])field(key).value=r?(key==='numbers'?r.numbers.join(','):['perWinner','pool'].includes(key)?r[key].toLocaleString('ko-KR'):r[key]):'';if(r)field('drawDate').value=r.date;d.querySelector('.round-details').open=!r;updatePrize();}
 function syncCalendar(){try{const mapped=resolvePurchaseDate(field('purchaseDate').value,field('purchaseTime').value,[...lotteryRecords.values()]);field('roundNumber').value=mapped.record.round;loadRound();d.querySelector('#calendar-hint').innerHTML=`<b>${date(mapped.purchaseDate)} ${mapped.purchaseTime}에 구매했다면</b><span>→ 제${mapped.record.round}회 · ${date(mapped.drawDate)} 추첨에 당첨</span><small>인생은 당첨일인 ${date(mapped.drawDate)}부터 시작합니다.</small>`;d.querySelector('button[type="submit"]').disabled=false;}catch(error){d.querySelector('#calendar-hint').innerHTML=`<span class="calendar-error">${escape(error.message)}</span>`;d.querySelector('button[type="submit"]').disabled=true;}applyReadability(d.querySelector('#calendar-hint'));}
 function setSelectionMode(mode){selectionMode=mode;const isCalendar=mode==='calendar';d.querySelector('#calendar-mode-panel').hidden=!isCalendar;d.querySelector('#round-mode-panel').hidden=isCalendar;field('purchaseDate').required=isCalendar;field('purchaseTime').required=isCalendar;d.querySelectorAll('[data-selection-mode]').forEach(button=>{const active=button.dataset.selectionMode===mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});if(isCalendar)syncCalendar();else{d.querySelector('button[type="submit"]').disabled=false;loadRound();}}
 applyReadability(d.querySelector('#round-info'));applyReadability(d);loadRound();field('purchaseDate').value=field('drawDate').value;d.querySelectorAll('[data-selection-mode]').forEach(button=>button.addEventListener('click',()=>setSelectionMode(button.dataset.selectionMode)));

 form.addEventListener('input',ev=>{if(['perWinner','pool','net'].includes(ev.target.name)){try{const original=ev.target.value,pos=ev.target.selectionStart,n=parseMoneyInput(original),formatted=n.toLocaleString('ko-KR');ev.target.value=formatted;if(typeof ev.target.setSelectionRange==='function'&&pos!==null){const next=Math.max(0,pos+formatted.length-original.length);ev.target.setSelectionRange(next,next);}updateMoneyHints();}catch{}}});
 form.addEventListener('change',ev=>{if(['purchaseDate','purchaseTime'].includes(ev.target.name)){syncCalendar();return;}if(ev.target.name==='roundNumber')loadRound();else if(['drawDate','numbers','bonus','winners','perWinner','pool','policy'].includes(ev.target.name)){activeStatus='내장 자료 기반 또는 사용자 수정 · 검증 필요';updatePrize();}});
 d.querySelectorAll('[data-round-preset]').forEach(button=>button.addEventListener('click',()=>{field('roundNumber').value=button.dataset.roundPreset;setSelectionMode('round');field('purchaseDate').value=field('drawDate').value;}));
 d.querySelector('#import-lottery').addEventListener('click',()=>d.querySelector('#lottery-file').click());
 d.querySelector('#lottery-file').addEventListener('change',async ev=>{try{const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('5MB 이하 JSON만 불러올 수 있습니다.');const data=JSON.parse(await file.text()),rows=Array.isArray(data)?data:(data.draws||[data]);if(!Array.isArray(rows)||rows.length>5000)throw Error('회차 배열을 확인해 주세요.');const checked=rows.map(validateRecord);const combined=new Map(lotteryRecords);checked.forEach(r=>combined.set(r.round,r));const serialized=JSON.stringify([...combined.values()]);localStorage.setItem(KEY+'-lottery',serialized);lotteryRecords=combined;loadRound();toast(`${checked.length}개 회차 자료를 불러왔어요. 내용의 진위는 별도 검증이 필요합니다.`);}catch(error){d.querySelector('#form-error').textContent=error.message;}finally{ev.target.value='';}});
 form.addEventListener('submit',ev=>{ev.preventDefault();try{const calendarEntry=selectionMode==='calendar'?resolvePurchaseDate(field('purchaseDate').value,field('purchaseTime').value,[...lotteryRecords.values()]):null;if(calendarEntry&&calendarEntry.record.round!==Number(field('roundNumber').value))throw Error('날짜에 해당하는 회차를 다시 확인해 주세요.');const rec=record(),prize=playerPrize(rec,field('policy').value),net=parseMoneyInput(field('net').value);if(!Number.isSafeInteger(net)||net<=0||net>prize.gross)throw Error('수령액은 세전 당첨금 이하의 양수여야 합니다.');const config={interestTax:true,historyEdition:6,balance:true,householdMode:field('householdMode')?.value||'manual',beta:true,difficulty:field('difficulty')?.value||'normal',learn:true,market:true,allocation:field('allocation')?.value||'balanced',name:field('name').value,age:Number(field('age').value),gender:field('gender').value,region:field('region').value,month:rec.date.slice(0,7),startDate:rec.date,round:`로또 제${rec.round}회`,gross:prize.gross,net,lifetime:true,purchaseSelection:calendarEntry?{mode:'calendar',date:calendarEntry.purchaseDate,time:calendarEntry.purchaseTime}:null,draw:{round:rec.round,numbers:rec.numbers,bonus:rec.bonus,winners:rec.winners,simulatedWinners:prize.simulatedWinners,hypothetical:prize.hypothetical}};const game=createGame(config);d.close();drawCeremony(game,rec,prize);}catch(error){d.querySelector('#form-error').textContent=error.message;}});
}

function drawCeremony(game,record,prize){
 const d=document.createElement('dialog');d.className='draw-dialog';let timers=[],done=false;
 d.innerHTML=`<div class="draw-heading"><span class="eyebrow">THE MOMENT EVERYTHING CHANGES</span><h2>제${record.round}회, 당신의 행운.</h2><p>${date(record.date)} · 기록된 당첨번호를 재현하는 연출입니다.</p></div><div class="lotto-machine mixing" aria-hidden="true"><div class="machine-sphere">${record.numbers.map((n,i)=>`<span class="machine-ball ball-${Math.ceil(n/10)}" style="--i:${i}">${n}</span>`).join('')}<div class="machine-hub">IF</div></div><div class="machine-base"><span>IF WORLD / LOTTO 6 · 45</span></div></div><div class="draw-number-row" aria-label="당첨번호">${record.numbers.map((n,i)=>`<span class="draw-slot" data-slot="${i}" aria-label="아직 공개하지 않은 번호">?</span>`).join('')}</div><div id="draw-result" class="draw-result" role="status"><span class="draw-status">공이 섞이고 있습니다…</span></div><div class="draw-actions"><button class="btn secondary" id="skip-draw">연출 건너뛰기</button><button class="btn" id="enter-life" disabled>이 삶 시작하기 →</button></div><p class="note">가상 티켓은 당첨번호와 일치하도록 설정됩니다. 실제 복권 구매·추첨이 아닙니다.</p>`;
 document.body.append(d);d.showModal();applyReadability(d);
 function reveal(i){const el=d.querySelector(`[data-slot="${i}"]`);el.textContent=record.numbers[i];el.className=`draw-slot revealed ball-${Math.ceil(record.numbers[i]/10)}`;el.setAttribute('aria-label',`당첨번호 ${record.numbers[i]}`);}
 function finish(){if(done)return;done=true;timers.forEach(clearTimeout);record.numbers.forEach((_,i)=>reveal(i));d.querySelector('.lotto-machine').classList.remove('mixing');d.querySelector('#draw-result').innerHTML=`<span class="mini-label">1등 당첨 · 가상 시나리오</span><h3>${won(game.gross)}</h3><p>실제 당첨자 ${record.winners}명 / 시뮬레이션 ${prize.simulatedWinners}명<br>설정 수령액 ${won(game.initial)} · 보너스 번호 ${record.bonus}</p>`;d.querySelector('#enter-life').disabled=false;d.querySelector('#skip-draw').hidden=true;applyReadability(d.querySelector('#draw-result'));}
 d.querySelector('#skip-draw').addEventListener('click',finish);
 d.querySelector('#enter-life').addEventListener('click',()=>{if(!done)return;state=game;save();landing=false;tab=state.market?'study':'life';d.close();render();window.scrollTo(0,0);toast('당첨일에서 당신의 다른 삶이 시작됐어요.');});
 d.addEventListener('close',()=>{timers.forEach(clearTimeout);d.remove();});
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)finish();else{record.numbers.forEach((_,i)=>timers.push(setTimeout(()=>{if(!d.open)return;reveal(i);d.querySelector('.draw-status').textContent=`${i+1}번째 번호 공개`;},1400+i*550)));timers.push(setTimeout(finish,4900));}
}

function birthSetup(){
 const d=document.createElement('dialog');d.className='setup-dialog birth-dialog';d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">START A LIFE / LEARN ECONOMIC HISTORY</span><h2>한 사람의 삶,<br>한 시대의 경제.</h2></div><button class="close-btn" data-close-purchase="yes" aria-label="닫기">×</button></div><form><p class="note">0세부터 가족의 생활을 관찰하며 성장합니다. 19세부터 직접 일과 자산을 선택합니다. 시작 시점은 2002년 12월~2026년 10월이며 그 이후는 가상 미래로 표시합니다.</p><div class="form-grid"><label class="field">이름<input name="name" maxlength="20" value="여행자" required></label><label class="field">태어나는 시점<input name="birthMonth" type="month" min="2002-12" max="2026-10" value="2002-12" required></label><label class="field">성별<select name="gender"><option value="unspecified">정하지 않음</option><option value="female">여성</option><option value="male">남성</option></select></label><label class="field">거주 지역<select name="region">${REGION_GROUPS.map(g=>`<optgroup label="${g.name}">${g.regions.map(id=>`<option value="${id}">${REGIONS[id].name}</option>`).join('')}</optgroup>`).join('')}</select></label><label class="field" style="grid-column:1/-1">가족의 가상 시작 자산 · 원<input name="capital" inputmode="numeric" value="20,000,000" required><small>학습용 설정값 · 실제 평균 가족 재산이 아닙니다.</small></label></div><label class="field spacer">가정환경<select name="householdMode"><option value="manual">직접 설정 · 기본 가계</option><option value="random">무작위 · 15/25/35/20/5 게임 배정</option></select><small>무작위는 재산·기존 부채·급여·주거를 배정합니다. 실제 계층 비율이 아닙니다. 로또 당첨금은 별도로 더하며, 출생 모드에서는 입력한 시작 자산을 대신합니다.</small></label><label class="field spacer">난이도 · 시작 후 변경 불가<select name="difficulty"><option value="normal">보통 · 통계 사기·가상 의료비</option><option value="hard">어려움 · 가상 위기 연습 추가</option></select><small>2024년 사기 피해율 연결 · 다른 연도 미연결. 의료비·어려움의 추가 사건은 실제 발생률이 아닌 가상 연습입니다.</small></label><p class="game-assumption">가족 소득은 모형 급여의 1.5배입니다. 아이는 직접 주식을 거래하거나 차·집을 사지 않습니다. 19세에는 자산을 유지한 채 자신의 급여로 전환하는 단순화를 사용합니다. 실제 상속·증여·가족 통계는 반영하지 않았습니다.</p><div class="form-error" role="alert"></div><div class="form-footer"><span class="note">${saved?'새 삶은 기존 슬롯을 덮어씁니다. 기존 기록을 먼저 내려받아 주세요.':'얼굴 없는 픽토그램이 삶의 단계를 보여줍니다.'}</span><button class="btn" type="submit">나의 첫 장면 열기 →</button></div></form>`;
 document.body.append(d);d.showModal();applyReadability(d);const form=d.querySelector('form');
 form.addEventListener('submit',ev=>{ev.preventDefault();try{const capital=parseMoneyInput(form.elements.capital.value);if(!Number.isSafeInteger(capital)||capital<100000||capital>1000000000000)throw Error('시작 자산은 100,000~1,000,000,000,000원 사이로 입력해 주세요.');state=createGame({startMode:'birth',interestTax:true,historyEdition:6,balance:true,householdMode:form.elements.householdMode?.value||'manual',beta:true,difficulty:form.elements.difficulty?.value||'normal',learn:true,market:true,allocation:'cash',lifetime:true,age:0,name:form.elements.name.value,gender:form.elements.gender.value,region:form.elements.region.value,month:form.elements.birthMonth.value,round:'출생부터 경제사 학습',net:capital,gross:capital});save();landing=false;tab='study';d.close();render();window.scrollTo(0,0);}catch(error){d.querySelector('.form-error').textContent=error.message;}});
 d.addEventListener('close',()=>d.remove());
}

function quickTrade(side){
 if(!state?.market)return toast('경제 시장을 먼저 연결하세요.');if(side==='sell'&&!MARKET_ASSETS.some(a=>(state.market.holdings[a.id]?.units||0)>0))return toast('아직 매도할 보유 자산이 없습니다.');
 const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>어떤 자산을 ${side==='buy'?'살까요':'팔까요'}?</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><form class="dialog-form"><label class="field">자산<select name="asset">${MARKET_ASSETS.filter(a=>side==='buy'||(state.market.holdings[a.id]?.units||0)>0).map(a=>`<option value="${a.id}">${a.name}</option>`).join('')}</select></label><button class="btn spacer" type="submit">금액과 수수료 확인 →</button></form>`;document.body.append(d);d.showModal();d.querySelector('form').addEventListener('submit',ev=>{ev.preventDefault();const id=d.querySelector('form').elements.asset.value;d.close();tradeReview(id,side);});d.addEventListener('close',()=>d.remove());
}
function choiceReview(id){const p=state.pending,c=choices(state).find(x=>x.id===id);if(!p||!c)return;const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>이 선택을 확정할까요?</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><div class="dialog-form"><span class="mini-label">${escape(p.title)}</span><h3>${escape(c.title)}</h3><p>${escape(c.detail)}</p><div class="confirmation-cost">선택 비용 <b>${won(choiceCost(state,id))}</b><br>현재 현금 <b>${won(state.cash)}</b></div><p class="note">확정한 사건 선택은 변경할 수 없습니다. 이후 금융 거래는 새로운 행동으로 진행할 수 있습니다.${p.kind==='risk'&&p.type!=='scam'&&choiceCost(state,id)>state.cash?' 현금으로 감당하지 못한 비용은 생활비 부족분에 기록됩니다.':''}</p><div class="dialog-action-row"><button class="btn secondary" data-close-purchase="yes">돌아가기</button><button class="btn" data-confirmed-choice="${escape(id)}" data-event-key="${escape(p.id+'|'+state.month)}">선택 확정</button></div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}
function termReview(id=null){const c=id?state.termDeposits?.contracts.find(c=>c.id===id):null;if(id&&(!c||c.status!=='active'))throw Error('진행 중인 계약을 확인해 주세요.');const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>${id?'계약형 예금 중도해지':'계약형 예금 조건 확인'}</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><form class="dialog-form"><p>실제 당시 은행상품이 아닌 교육용 계약입니다. 확정 전에는 자산이 바뀌지 않습니다.</p>${id?'':`<label class="field">가입 금액 · 원<input name="amount" inputmode="numeric" value="1,000,000" required></label><label class="field">예치 기간<select name="depositPeriod">${[3,6,12,24].map(n=>`<option value="${n}" ${n===12?'selected':''}>${n}개월</option>`).join('')}</select></label>`}<div id="term-preview" aria-live="polite"></div><p>중도해지 연 금리는 0.1%와 계약 금리 중 낮은 값입니다. 월 단위 단리·일시 지급의 게임 규칙이며 실제 은행상품 조건이 아닙니다. 한 달이 지나기 전 해지하면 이자는 0원입니다.</p><label class="policy-consent"><input name="termConsent" type="checkbox" required>교육용 계약과 자금이 묶이는 조건을 확인했습니다.</label><div class="form-error" role="alert"></div><button class="btn spacer" type="submit">${id?'해지하고 원금·세후 이자 받기':'이 조건으로 계약 확정'}</button></form>`;document.body.append(d);d.showModal();const f=d.querySelector('form');function preview(){try{const q=id?termPayout(state,c):quoteTermDeposit(state,parseMoneyInput(f.elements.amount.value),Number(f.elements.depositPeriod.value),gameEconomy(state).deposit);const r=id?q:q.expected;d.querySelector('#term-preview').innerHTML=`${id?'':`<p>현재 모형 금리 연 <b>${(q.rateBP/100).toFixed(2)}%</b> 고정 · ${date(q.maturity)} 자동 만기 입금</p>`}<div class="protection-metrics"><div><span>원금</span><b>${won(r.principal)}</b></div><div><span>${id?'현재 해지':'계약 유지 시 만기'} 세전 이자</span><b>${won(r.gross)}</b></div><div><span>이자 공제 모형</span><b>−${won(r.total)}</b></div><div><span>원금 + 세후 이자 입금</span><b>${won(r.payout)}</b></div></div><p>원금은 수익이 아닙니다. 미지급 이자는 매달 현금으로 들어오지 않습니다. 만기 세금은 현재 연결된 시기별 기본 세율을 유지하는 예상이며 미래 세법을 확정하지 않습니다.</p>`;d.querySelector('.form-error').textContent='';d.querySelector('button[type="submit"]').disabled=f.elements.termConsent.checked!==true||state.ended||Boolean(state.pending);}catch(error){d.querySelector('#term-preview').innerHTML='';d.querySelector('.form-error').textContent=error.message;d.querySelector('button[type="submit"]').disabled=true;}}f.addEventListener('input',preview);f.addEventListener('change',preview);f.addEventListener('submit',ev=>{ev.preventDefault();try{if(f.elements.termConsent.checked!==true)throw Error('계약 조건을 먼저 확인해 주세요.');if(id)closeTermDeposit(state,id);else openTermDeposit(state,parseMoneyInput(f.elements.amount.value),Number(f.elements.depositPeriod.value),gameEconomy(state).deposit,true);save();d.close();render();toast(id?'해지 입금과 공제를 장부에 기록했습니다.':'금리·금액·기간을 고정한 계약을 기록했습니다.');}catch(error){d.querySelector('.form-error').textContent=error.message;}});d.addEventListener('close',()=>d.remove());preview();}
function protectionReview(){if(!protectionRule(state.month))throw Error('이 시기의 보호 규칙은 미연결입니다.');const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>금융회사 분산 비교</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><form class="dialog-form"><p>학습용 비교입니다. 계산과 닫기는 게임 자산·시간·선택 기록을 바꾸지 않습니다.</p><label class="field">비교 원금 · 원<input name="principal" inputmode="numeric" value="${(Math.round(state.deposit)+termPrincipal(state)).toLocaleString('ko-KR')}" required></label><label class="field">가정한 소정의 이자 · 원<input name="interest" inputmode="numeric" value="0" required></label><label class="field">나눌 통장 또는 금융회사 수<select name="companies">${[1,2,3,5,10,20].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n}개</option>`).join('')}</select></label><button class="btn secondary" type="submit">조건으로 비교하기</button><div class="form-error" role="alert"></div><div id="protection-preview" aria-live="polite"></div><p>같은 금융회사에 통장만 나누기와 서로 다른 금융회사에 균등 분산을 비교합니다. 실제 계좌 개설·자금 이동이 아닙니다. 소정의 이자는 직접 가정한 값이며 약정 이자와 같다고 보지 않습니다.</p></form>`;document.body.append(d);d.showModal();const f=d.querySelector('form');function preview(){const out=d.querySelector('#protection-preview');try{const q=compareProtection(state.month,parseMoneyInput(f.elements.principal.value),parseMoneyInput(f.elements.interest.value),Number(f.elements.companies.value));d.querySelector('.form-error').textContent='';out.innerHTML=`<section><h3>같은 금융회사 · 통장만 나누기</h3>${renderProtectionResult(q.same,{won})}</section><section><h3>서로 다른 금융회사 · 균등 분산</h3>${renderProtectionResult(q.separate,{won})}</section><p>한도 초과액은 확정 손실액이 아닙니다. 실제 보험금 지급 심사는 별도입니다.</p>`;}catch(error){out.innerHTML='';d.querySelector('.form-error').textContent=error.message;}}f.addEventListener('input',preview);f.addEventListener('change',preview);f.addEventListener('submit',ev=>{ev.preventDefault();preview();});d.addEventListener('close',()=>d.remove());preview();}
function reserveReview(side){const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>예금잔액 ${side==='deposit'?'넣기':'인출'}</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><form class="dialog-form"><label class="field">금액 · 원<input name="amount" inputmode="numeric" value="1,000,000" required></label><p class="note">현재 예금은 변동금리 게임 잔액입니다. 실제 당시 정기예금의 계약·만기·중도해지 상품은 미연결입니다.</p><div id="reserve-protection-preview" aria-live="polite"></div><div class="form-error" role="alert"></div><button class="btn spacer" type="submit">금액 확인 후 ${side==='deposit'?'넣기':'인출'} 확정</button></form>`;document.body.append(d);d.showModal();const f=d.querySelector('form');function preview(){try{d.querySelector('#reserve-protection-preview').innerHTML=reserveProtectionPreview(state,side,parseMoneyInput(f.elements.amount.value),{won});d.querySelector('.form-error').textContent='';d.querySelector('button[type="submit"]').disabled=false;}catch(error){d.querySelector('#reserve-protection-preview').innerHTML='';d.querySelector('.form-error').textContent=error.message;d.querySelector('button[type="submit"]').disabled=true;}}f.addEventListener('input',preview);f.addEventListener('submit',ev=>{ev.preventDefault();try{moveReserve(state,side,parseMoneyInput(f.elements.amount.value));save();d.close();render();toast('금액을 이동했습니다. 순자산은 유지됩니다.');}catch(error){d.querySelector('.form-error').textContent=error.message;}});d.addEventListener('close',()=>d.remove());preview();}
function creditReview(kind,id=null){
 const d=document.createElement('dialog');d.className='purchase-dialog credit-dialog';const contract=state.credit?.contracts.find(c=>c.id===id),remainder=kind==='repay'?(contract?.balance||0)+(contract?.arrearsInterest||0):livingShortfall(state);
 d.innerHTML=`<div class="dialog-head"><h2>${kind==='borrow'?'대출 조건 확인':kind==='repay'?'대출 추가 상환':'생활비 부족분 상환'}</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><form class="dialog-form"><label class="field">${kind==='borrow'?'빌릴':'상환할'} 금액 · 원<input name="amount" inputmode="numeric" value="${(kind==='borrow'?1000000:Math.min(state.cash,remainder)).toLocaleString('ko-KR')}" required></label>${kind==='borrow'?'<label class="field spacer">상환 기간<select name="term"><option value="12">12개월</option><option value="24">24개월</option><option value="36" selected>36개월</option><option value="60">60개월</option></select></label>':''}<div id="credit-preview" class="credit-preview" aria-live="polite"></div>${kind==='borrow'?'<label class="credit-consent"><input name="modelConsent" type="checkbox" required> 금리·한도·심사가 실제 당시 은행상품이 아닌 교육용 가정임을 확인했습니다.</label>':'<p class="note">상환은 현금과 부채를 함께 줄입니다. 이 모형의 중도상환수수료는 0원이며 실제 은행상품 조건이 아닙니다.</p>'}<div class="form-error" role="alert"></div><button class="btn spacer" type="submit">${kind==='borrow'?'대출 계약':'상환'} 확정</button></form>`;
 document.body.append(d);d.showModal();const f=d.querySelector('form');function preview(){try{const amount=parseMoneyInput(f.elements.amount.value);if(kind==='borrow'){const q=quoteLoan(state,amount,Number(f.elements.term.value),earnedIncome(state));d.querySelector('#credit-preview').innerHTML=`<div><span>고정 연 금리 · 모형</span><b>${(q.rate*100).toFixed(2)}%</b></div><div><span>첫 달 원금</span><b>${won(q.firstPrincipal)}</b></div><div><span>첫 달 이자</span><b>${won(q.firstInterest)}</b></div><div><span>첫 달 원리금</span><b>${won(q.payment)}</b></div><p class="note">원금균등 · 다음 달부터 월 납부 · 미납은 별도 기록</p>${q.disabled?`<p class="form-error">${escape(q.reason)}</p>`:''}`;d.querySelector('button[type="submit"]').disabled=q.disabled||f.elements.modelConsent.checked!==true;}else{const q=kind==='repay'?quotePrepayment(state,id,amount):null;d.querySelector('#credit-preview').innerHTML=`남은 부채 <b>${won(remainder)}</b><br>현재 현금 <b>${won(state.cash)}</b>${q?.reason?`<p>${escape(q.reason)}</p>`:''}`;d.querySelector('button[type="submit"]').disabled=Boolean(q?.disabled)||amount<=0||amount>state.cash||amount>remainder;}}catch(error){d.querySelector('#credit-preview').textContent=error.message;d.querySelector('button[type="submit"]').disabled=true;}}
 f.addEventListener('input',preview);f.addEventListener('change',preview);f.addEventListener('submit',ev=>{ev.preventDefault();try{const amount=parseMoneyInput(f.elements.amount.value);if(kind==='borrow')borrow(state,amount,Number(f.elements.term.value),earnedIncome(state),f.elements.modelConsent.checked===true);else if(kind==='repay')prepay(state,id,amount);else repayShortfall(state,amount);trackLife(state,expenses(state));save();d.close();render();toast(kind==='borrow'?'대출 계약을 확정했습니다. 현금과 부채가 함께 늘었습니다.':'상환을 기록했습니다.');}catch(error){d.querySelector('.form-error').textContent=error.message;preview();}});d.addEventListener('close',()=>d.remove());preview();
}
function interestTaxReview(){if(!canEnableInterestTax(state))throw Error('현재 선택을 먼저 마쳐 주세요.');const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>예금 이자 공제 연결</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><div class="dialog-form"><p>다음 진행 월부터 일반과세 공제 모형을 연결합니다. 기존 자산·공제·장부는 그대로 둡니다. 은행상품·만기·중도해지·종합과세 정산은 재현하지 않습니다.</p><div class="dialog-action-row"><button class="btn secondary" data-close-purchase="yes">취소</button><button class="btn" data-interest-tax-confirm="yes">이후부터 연결</button></div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}
function historyUpgradeReview(){if(!canUpgradeHistory(state))throw Error('현재 선택을 먼저 마쳐 주세요.');const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>새 역사 자료 연결</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><div class="dialog-form"><p>누락 사건 8개와 시작 전 배경 2개를 포함한 자료 6판입니다. 이후 진행하는 달부터 연결합니다. 지나간 사건·자산·확정 선택은 바꾸지 않습니다.</p><div class="dialog-action-row"><button class="btn secondary" data-close-purchase="yes">취소</button><button class="btn" data-history-confirm="yes">이후부터 연결</button></div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}
function insuranceReview(){const on=!state.household?.privateInsurance,d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>${on?'보험 모형 가입':'보험 모형 해지'}</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><div class="dialog-form"><p>월 기본 80,000원 × 물가 배율. 가입하면 가상 입원비의 80%를 연간 물가 조정 1,000만원 한도로 차감합니다. 실제 보험상품·약관·세금 자료는 아닙니다. 사기·실직·자동차 수리비는 보장하지 않습니다.</p><div class="dialog-action-row"><button class="btn secondary" data-close-purchase="yes">취소</button><button class="btn" data-insurance-confirm="${on?'on':'off'}">선택 확정</button></div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}
function comfortReview(id){const c=COMFORT_CHOICES[id];if(!c)return;const d=document.createElement('dialog');d.className='purchase-dialog';d.innerHTML=`<div class="dialog-head"><h2>${escape(c.title)}</h2><button data-close-purchase="yes" aria-label="닫기">×</button></div><div class="dialog-form"><p>가상 비용 ${won(c.cost)} · 만족 +${c.happiness} · 운 체감 +${c.feeling}</p><p>실제 서비스 가격이 아닙니다. 사고·사기 확률, 자산 가격과 객관적 총운은 바뀌지 않습니다. 이달에는 한 번만 선택할 수 있습니다.</p><div class="dialog-action-row"><button class="btn secondary" data-close-purchase="yes">취소</button><button class="btn" data-comfort-confirm="${escape(id)}">선택 확정</button></div></div>`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());applyReadability(d);}
function exportReceipt(){const text=receiptDocument(state,{escape,won,date}),blob=new Blob([text],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`if-world-life-${state.month}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('영수증 HTML을 내려받았습니다. 브라우저에서 열어 인쇄하거나 PDF로 저장할 수 있어요.');}

function exportGame(){if(!state&&!saved)return toast('아직 내려받을 기록이 없어요.');const s=state||saved;const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`if-world-${s.month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('기록을 내려받았어요. 불러오기로 이어서 플레이할 수 있어요.');}
document.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el||el.disabled)return;try{if(el.dataset.helpSection){helpSection=normalizeHelpSection(el.dataset.helpSection);render();return;}if(el.dataset.scroll){menuOpen=false;$('#primary-nav')?.classList.remove('is-open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');document.getElementById(el.dataset.scroll)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}if(el.dataset.scenario){setup(el.dataset.scenario);return;}if(el.dataset.pace){storyMode=el.dataset.pace==='story';try{localStorage.setItem(KEY+'-pace',storyMode?'story':'manual');}catch{}render();toast(storyMode?'선택 후 다음 사건으로 자동 이동해요.':'직접 시간을 진행할 수 있어요.');return;}if(el.dataset.interestTaxReview){interestTaxReview();return;}if(el.dataset.interestTaxConfirm){enableInterestTax(state);save();el.closest('dialog')?.close();render();toast('이후 월부터 이자 공제를 연결했습니다.');return;}if(el.dataset.historyUpgrade){historyUpgradeReview();return;}if(el.dataset.historyConfirm){upgradeHistory(state);save();el.closest('dialog')?.close();render();toast('이후 진행에 새 역사 자료를 연결했습니다.');return;}if(el.dataset.insuranceReview){insuranceReview();return;}if(el.dataset.insuranceConfirm){setInsurance(state,el.dataset.insuranceConfirm==='on');save();el.closest('dialog')?.close();render();toast('보험 모형 선택을 기록했습니다.');return;}if(el.dataset.comfortOpen){comfortReview(el.dataset.comfortOpen);return;}if(el.dataset.comfortConfirm){chooseComfort(state,el.dataset.comfortConfirm);save();el.closest('dialog')?.close();render();toast('만족감과 운 체감을 기록했습니다.');return;}if(el.dataset.quickTrade){quickTrade(el.dataset.quickTrade);return;}if(el.dataset.termOpen){termReview();return;}if(el.dataset.termClose){termReview(el.dataset.termClose);return;}if(el.dataset.protectionOpen){protectionReview();return;}if(el.dataset.reserveOpen){reserveReview(el.dataset.reserveOpen);return;}if(el.dataset.creditOpen){creditReview('borrow');return;}if(el.dataset.creditRepay){creditReview('repay',el.dataset.creditRepay);return;}if(el.dataset.shortfallOpen){creditReview('shortfall');return;}if(el.dataset.avatarMotion){avatarMotion=!avatarMotion;render();toast(avatarMotion?'캐릭터 움직임을 재생합니다.':'캐릭터 움직임을 멈췄어요.');return;}if(el.dataset.tab){menuOpen=false;tab=el.dataset.tab;render();return;}if(el.dataset.shop){shopCategory=el.dataset.shop;tab='shop';render();return;}if(el.dataset.shopCategory){shopCategory=el.dataset.shopCategory;render();return;}if(el.dataset.domesticEnable){enableDomesticEconomy(state);save();render();toast('이후 월부터 내수 환경을 가게 매출에 반영해요.');return;}if(el.dataset.marketLife){setMarketLifeEvents(state,el.dataset.marketLife==='on');save();render();toast(state.market.lifeEvents?'삶의 이야기와 시장을 함께 진행해요.':'앞으로 큰 시장 사건 중심으로 진행해요.');return;}if(el.dataset.marketEnable){initializeMarket(state,'cash');save();render();toast('기존 평가액을 유지하고 경제 시장을 열었어요.');return;}if(el.dataset.marketStock){marketStock=el.dataset.marketStock;render();return;}if(el.dataset.marketPeriod){marketPeriod=Number(el.dataset.marketPeriod);render();return;}if(el.dataset.tradeOpen){const [id,side]=el.dataset.tradeOpen.split(':');tradeReview(id,side);return;}if(el.dataset.tradeAll){tradeReview(el.dataset.tradeAll,'sell',true);return;}if(el.dataset.storyFocus){setFocus(state,el.dataset.storyFocus);save();render();toast('내 시간의 방향을 바꿨어요.');return;}if(el.dataset.moveReview){const region=$('#move-region')?.value;moveReview(region);return;}if(el.dataset.moveConfirm){moveRegion(state,el.dataset.moveConfirm);save();el.closest('dialog')?.close();render();toast('새로운 지역에서 일상이 시작됩니다.');return;}if(el.dataset.lifeReview){const [kind,id]=el.dataset.lifeReview.split(':');lifeReview(kind,id);return;}if(el.dataset.lifeConfirm||el.dataset.lifeDo){const [kind,id]=(el.dataset.lifeConfirm||el.dataset.lifeDo).split(':');const result=doLife(state,kind,id);el.closest('dialog')?.close();if(result?.shop){tab='shop';shopCategory=result.shop;}save();render();toast(kind==='bucket'?'나의 버킷리스트를 바꿨어요.':'나의 일상과 추억에 남겼어요.');return;}if(el.dataset.buy){purchaseReview(el.dataset.buy);return;}if(el.dataset.confirmPurchase){purchase(state,el.dataset.confirmPurchase);tab='world';save();el.closest('dialog')?.close();render();toast('내가 고른 생활이 보유 목록에 남았어요.');return;}if(el.dataset.sellOwned){sellCollectionItem(state,el.dataset.sellOwned);save();render();toast('소장품을 정리하고 현금을 회수했어요.');return;}if(el.dataset.closePurchase){el.closest('dialog')?.close();return;}if(el.dataset.choice){choiceReview(el.dataset.choice);return;}if(el.dataset.confirmedChoice){if(el.dataset.eventKey!==state.pending?.id+'|'+state.month)throw Error('선택한 사건이 바뀌었습니다. 다시 확인하세요.');el.disabled=true;const decisionId=el.dataset.confirmedChoice;const preparation=state.pending?.kind==='history-study'&&state.pending.stage==='before';const reviewing=state.pending?.kind==='history-study'&&decisionId==='review';const before=monthIndex(state.month);decide(state,decisionId);const openMarket=decisionId==='market-review';if(openMarket)tab='market';const openShop=decisionId==='wish'||decisionId.startsWith('shop-');if(openShop){shopCategory=decisionId.startsWith('shop-')?decisionId.slice(5):'home';tab='shop';}if(decisionId==='first-week')tab='world';if(reviewing)tab='notebook';if(storyMode&&!state.rules&&!preparation&&!reviewing&&!openMarket&&!openShop&&decisionId!=='first-week'&&!state.pending&&!state.ended)advance(state,12);const passed=monthIndex(state.month)-before;save();el.closest('dialog')?.close();render();toast(passed?`선택을 기록하고 ${passed}개월 뒤의 이야기에 도착했어요.`:'선택이 기록되었어요.');return;}if(el.dataset.action){action(state,el.dataset.action);save();render();toast('자산과 생활에 반영했어요.');return;}if(el.dataset.advance){advance(state,Number(el.dataset.advance));save();render();toast(state.pending?'선택할 사건을 만났어요.':state.ended?'이 삶의 기록이 완성되었어요.':'시간이 흘렀어요.');return;}switch(el.dataset.ui){case 'menu':menuOpen=!menuOpen;const nav=$('#primary-nav');nav?.classList.toggle('is-open',menuOpen);el.setAttribute('aria-expanded',String(menuOpen));el.setAttribute('aria-label',menuOpen?'메뉴 닫기':'메뉴 열기');break;case 'learn-new':menuOpen=false;birthSetup();break;case 'new':menuOpen=false;setup();break;case 'close':$('#setup')?.close();break;case 'home':menuOpen=false;landing=true;render();window.scrollTo(0,0);break;case 'resume':menuOpen=false;state=structuredClone(saved);landing=false;tab=state.market?'study':'life';render();break;case 'guide':menuOpen=false;if(tab!=='guide'||landing)helpReturn={landing,tab};landing=false;tab='guide';helpSection='play';render();window.scrollTo(0,0);break;case 'guide-back':menuOpen=false;landing=helpReturn.landing;tab=helpReturn.tab;render();break;case 'data':menuOpen=false;landing=false;tab='data';render();break;case 'receipt':exportReceipt();break;case 'export':exportGame();break;case 'import':$('#import-file').click();break;}}catch(error){toast(error.message);}});
document.addEventListener('change',ev=>{if(ev.target.id==='log-filter'){filter=ev.target.value;render();}});
$('#import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('5MB 이하의 기록 파일만 불러올 수 있습니다.');const parsed=JSON.parse(await file.text());if(!validateSave(parsed))throw Error('IF 세계 기록 형식이 올바르지 않습니다.');if(saved&&!confirm('현재 브라우저의 기록을 불러온 기록으로 바꿀까요? 기존 기록은 먼저 내려받아 보관하세요.'))return;state=parsed;menuOpen=false;save();landing=false;tab='life';render();toast('기록을 불러왔어요.');}catch(error){toast(error.message);}finally{ev.target.value='';}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&menuOpen){menuOpen=false;$('#primary-nav')?.classList.remove('is-open');const toggle=document.querySelector('.menu-toggle');toggle?.setAttribute('aria-expanded','false');toggle?.setAttribute('aria-label','메뉴 열기');toggle?.focus();}});
